async function isAdminAllowed_(discordId, env) {
  const idStr = discordId.toString();
  if (ADMIN_IDS.includes(idStr)) return true;
  try {
    const accessToken = await getGoogleAccessToken(env);
    const adminListData = await getCachedSheetData_('adminList:' + env.SHEET_ID, () => fetchOptionalSheet_(accessToken, env.SHEET_ID, ADMIN_LIST_SHEET_NAME_));
    for (let i = 1; i < adminListData.length; i++) {
      const rowId = adminListData[i][0] ? adminListData[i][0].toString().replace("'", '').trim() : '';
      if (rowId && rowId === idStr) return true;
    }
  } catch (e) {
  }
  return false;
}

const VAPID_PUBLIC_KEY = 'BEtm2b_TlQ7e8oKiFmAa69I3e01t0zfPNxggs1eBkVZCpZuheOf6o7wjQpgxZdzcMbKikUUCYQ2SkD1T0fkbDRk';
const VAPID_PRIVATE_KEY = 'y886Tq9Ahhj3vyAeS1LYzfT51O2Urr7Q4jIuHGKPprM';
const VAPID_SUBJECT = 'mailto:admin@example.com';

function b64urlToBuf_(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  const bin = atob(s);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf;
}
function bufToB64url_(buf) {
  let bin = '';
  const bytes = new Uint8Array(buf);
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function concatBytes_(...arrs) {
  let total = arrs.reduce((s, a) => s + a.length, 0);
  let out = new Uint8Array(total);
  let off = 0;
  for (const a of arrs) { out.set(a, off); off += a.length; }
  return out;
}
function rawPointToJwk_(rawBytes) {
  const x = rawBytes.slice(1, 33);
  const y = rawBytes.slice(33, 65);
  return { kty: 'EC', crv: 'P-256', x: bufToB64url_(x), y: bufToB64url_(y), ext: true };
}
async function hmacSha256_(keyBytes, dataBytes) {
  const key = await crypto.subtle.importKey('raw', keyBytes, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, dataBytes);
  return new Uint8Array(sig);
}
async function hkdfExpand_(prk, info, length) {
  const data = concatBytes_(info, new Uint8Array([1]));
  const out = await hmacSha256_(prk, data);
  return out.slice(0, length);
}

async function createVapidJwt_(audience) {
  const header = { typ: 'JWT', alg: 'ES256' };
  const payload = { aud: audience, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: VAPID_SUBJECT };
  const headerB64 = bufToB64url_(new TextEncoder().encode(JSON.stringify(header)));
  const payloadB64 = bufToB64url_(new TextEncoder().encode(JSON.stringify(payload)));
  const unsigned = `${headerB64}.${payloadB64}`;

  const publicBytes = b64urlToBuf_(VAPID_PUBLIC_KEY);
  const jwk = rawPointToJwk_(publicBytes);
  jwk.d = VAPID_PRIVATE_KEY;
  jwk.key_ops = ['sign'];

  const key = await crypto.subtle.importKey('jwk', jwk, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
  const sig = new Uint8Array(await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, new TextEncoder().encode(unsigned)));
  return `${unsigned}.${bufToB64url_(sig)}`;
}

async function encryptPushPayload_(ua_public_b64, auth_secret_b64, plaintext) {
  const ua_public_bytes = b64urlToBuf_(ua_public_b64);
  const auth_secret = b64urlToBuf_(auth_secret_b64);
  const salt = crypto.getRandomValues(new Uint8Array(16));

  const ephemeralKeyPair = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']);
  const as_public_bytes = new Uint8Array(await crypto.subtle.exportKey('raw', ephemeralKeyPair.publicKey));

  const ua_public_jwk = rawPointToJwk_(ua_public_bytes);
  const ua_public_key = await crypto.subtle.importKey('jwk', ua_public_jwk, { name: 'ECDH', namedCurve: 'P-256' }, false, []);

  const ecdh_secret = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: ua_public_key }, ephemeralKeyPair.privateKey, 256));

  const info_prefix = new TextEncoder().encode('WebPush: info\0');
  const auth_info = concatBytes_(info_prefix, ua_public_bytes, as_public_bytes);

  const PRK_key = await hmacSha256_(auth_secret, ecdh_secret);
  const IKM = await hkdfExpand_(PRK_key, auth_info, 32);

  const PRK = await hmacSha256_(salt, IKM);
  const cek = await hkdfExpand_(PRK, new TextEncoder().encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdfExpand_(PRK, new TextEncoder().encode('Content-Encoding: nonce\0'), 12);

  const cekKey = await crypto.subtle.importKey('raw', cek, { name: 'AES-GCM' }, false, ['encrypt']);
  const padded = concatBytes_(new TextEncoder().encode(plaintext), new Uint8Array([2]));
  const ciphertext = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: nonce, tagLength: 128 }, cekKey, padded));

  const recordSize = new Uint8Array(4);
  new DataView(recordSize.buffer).setUint32(0, 4096, false);
  const header = concatBytes_(salt, recordSize, new Uint8Array([as_public_bytes.length]), as_public_bytes);
  return concatBytes_(header, ciphertext);
}

async function sendWebPush_(subscription, payloadObj) {
  try {
    const endpoint = subscription.endpoint;
    const ua_public_b64 = subscription.keys.p256dh;
    const auth_secret_b64 = subscription.keys.auth;
    const plaintext = JSON.stringify(payloadObj);

    const encryptedBody = await encryptPushPayload_(ua_public_b64, auth_secret_b64, plaintext);
    const endpointUrl = new URL(endpoint);
    const audience = `${endpointUrl.protocol}//${endpointUrl.host}`;
    const vapidJwt = await createVapidJwt_(audience);

    const res = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/octet-stream',
        'Content-Encoding': 'aes128gcm',
        'TTL': '86400',
        'Authorization': `vapid t=${vapidJwt}, k=${VAPID_PUBLIC_KEY}`,
      },
      body: encryptedBody,
    });

    return { success: res.ok, status: res.status, error: res.ok ? null : await res.text() };
  } catch (e) {
    return { success: false, status: 0, error: e.message };
  }
}

