        if (!actionType) return jsonResponse({ status: 'error', message: '缺少actionType' }, corsHeaders);
        const accessToken = await getGoogleAccessToken(env);
        const rows = await fetchRecentHistoryTail(accessToken, env.SHEET_ID, 60);
        const result = findInstrumentedActionResult_(discordId, actionType, sinceTs, rows);
