        if (!activityData) activityData = await getCachedSheetData_('bingoActivities:' + env.SHEET_ID, () => fetchBingoActivitySheet(accessToken, env.SHEET_ID));
        const t2 = Date.now();
        const result = buildBingoActivityList(activityData);
        const t3 = Date.now();
        result.debugTiming = { getAccessToken_ms: t1 - t0, fetchBingoActivities_ms: t2 - t1, buildBingoActivityList_ms: t3 - t2, total_ms: t3 - t0 };
        return jsonResponse(result, corsHeaders);
