      if (action === 'auctions') {
        const t0 = Date.now();
        const accessToken = await getGoogleAccessToken(env);
        const t1 = Date.now();
        // 快速模式:拍賣列表走DO共用快照(不管幾個人開著拍賣視窗,3 秒內只讀一次Google;各isolate不會各讀各的)
        let auctionSheets = null;
        if (env.GENERAL_ITEM_LOCK && env.FAST_BUY === '1') { try { auctionSheets = (await snapApi_(env).get('aucall', 3000)).rows; } catch (e) { auctionSheets = null; } }
        if (!auctionSheets) auctionSheets = await getCachedSheetData_('auctions:' + env.SHEET_ID, () => fetchAuctionSheets(accessToken, env.SHEET_ID));
        const t2 = Date.now();
        let as_ = auctionSheets;
        if (env.GENERAL_ITEM_LOCK && env.FAST_BUY === '1') { try { const o_ = await doCall_(env, 'auc:main', 'aucOverlay', {}); if (o_ && o_.ov && Object.keys(o_.ov).length) as_ = applyAucOverlay_(auctionSheets, o_.ov); } catch (e) {} }
        const result = buildAuctions(discordId, as_.auction, as_.bid, as_.player, as_.roleMap, as_.categoryOrder);
        const t3 = Date.now();
        result.debugTiming = { getAccessToken_ms: t1 - t0, fetchAuctionSheets_ms: t2 - t1, buildAuctions_ms: t3 - t2, total_ms: t3 - t0 };
        return jsonResponse(result, corsHeaders);
      }

      // 🌟🆕 抽獎投票名單改走Worker:原本index.html的showRaffleParticipants()是直接打GAS_API_URL
      // (doGet的getRaffleParticipants),跟這個系統裡其他所有「單純讀取、不用寫入」的清單(history/
      // bingoActivities/auctions...)都已經改走這支Worker、只有這個還留在GAS不一樣——GAS Web App本身
      // 沒有真正的請求佇列,冷啟動/排隊等鎖偶爾會拖到快10秒甚至逾時,玩家點開「查看名單」彈窗常常卡在
      // 「讀取中...」轉圈圈轉很久甚至讀不出來。這裡在Worker端加一支鏡像版本(邏輯跟Code_real.gs的
      // getRaffleParticipants完全一致:票數紀錄表依itemId篩選、依加權票數由高到低排序、算出各自的
      // 中獎機率%),玩家表共用'player:'+SHEET_ID快取、票數紀錄表共用'raffleTickets:'+SHEET_ID快取
      // (跟botGetRaffleInfo同一把),速度快也穩定。GAS那邊的getRaffleParticipants原封不動保留著,
      // 後台管理畫面如果還有地方在用就不受影響。
      if (action === 'raffleParticipants') {
        // 🌟🔧 小孩回報過這個action偶爾回500(Cloudflare原生錯誤頁,不是JSON)——照理說最外層
        // (handleFetch_外面那層try/catch,見本檔案436行附近)應該會把任何例外轉成status:200的JSON
        // 錯誤回應,不該讓玩家看到原生500頁面;但同檔案裡其他單一action(例如botGetAuctionInfo)
        // 也都額外包了一層自己的try/catch,屬於這份檔案一貫的「多一層防護」慣例。這裡補上同款的
        // 區塊內try/catch,至少能把真正的錯誤訊息(例如Google API暫時性錯誤、quota限流)帶回給前端
        // 顯示,不是只看到籠統的「讀取失敗,請稍後再試」,方便之後若再發生時從訊息內容判斷根因。
        try {
          const t0 = Date.now();
          const itemId = (url.searchParams.get('itemId') || '').toString().trim();
          if (!itemId) return jsonResponse({ status: 'error', message: '缺少itemId' }, corsHeaders);
          const accessToken = await getGoogleAccessToken(env);
          const t1 = Date.now();
          const [ticketData, playerData, shopDataForRaffle] = await Promise.all([
            getCachedSheetData_('raffleTickets:' + env.SHEET_ID, () => fetchOptionalSheet_(accessToken, env.SHEET_ID, RAFFLE_TICKET_SHEET_NAME)),
            getCachedSheetData_('player:' + env.SHEET_ID, () => fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player)),
            getCachedSheetData_('shop:' + env.SHEET_ID, () => fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.shop)),
          ]);
          const t2 = Date.now();

          // 🌟🔧 修正bug(跟Code_real.gs的getRaffleParticipants同步修正):已經開獎過的話,額外回傳得獎名單
          // (drawn:true、winners,玩家反應「得獎名單看不到」)——但投票名單(list,票數/機率)不管有沒有
          // 開獎都照樣算、照樣回傳,不拿掉(管理員反應「後臺沒總名單」,後台查核需要完整投票紀錄)。
          let drawn = false, winners = null, noWinnerNote = null;
          for (let si = 1; si < shopDataForRaffle.length; si++) {
            const siItemId = shopDataForRaffle[si][18] ? shopDataForRaffle[si][18].toString().trim() : '';
            if (siItemId !== itemId) continue;
            const raffleResultRaw = shopDataForRaffle[si][41] ? shopDataForRaffle[si][41].toString().trim() : '';
            if (!raffleResultRaw) break;
            drawn = true;
            const raffleResult = safeParseJSON(raffleResultRaw);
            if (!raffleResult || !Array.isArray(raffleResult)) {
              winners = [];
              noWinnerNote = (raffleResult && raffleResult.note) || '無人投票或未設定獎池,活動自動關閉';
            } else {
              winners = raffleResult.map((w) => ({ discordId: w.discordId, name: getPlayerDisplayNameFromData(w.discordId, playerData) || w.discordId, prize: w.prize }));
            }
            break;
          }

          const entries = [];
          let totalWeighted = 0;
          for (let t = 1; t < ticketData.length; t++) {
            const row = ticketData[t];
            if (!row[0] || row[0].toString() !== itemId) continue;
            const uid = row[1] ? row[1].toString().replace("'", '') : '';
            if (!uid) continue;
            const raw = parseInt(row[2]) || 0;
            const weighted = parseFloat(row[3]) || 0;
            if (weighted <= 0) continue;
            entries.push({
              discordId: uid,
              name: getPlayerDisplayNameFromData(uid, playerData) || uid,
              raw, weighted,
            });
            totalWeighted += weighted;
          }
          entries.forEach((e) => { e.odds = totalWeighted > 0 ? Math.round((e.weighted / totalWeighted) * 10000) / 100 : 0; });
          entries.sort((a, b) => b.weighted - a.weighted);

          const t3 = Date.now();
          return jsonResponse({
            status: 'success', drawn, winners, noWinnerNote, totalWeighted, list: entries,
            debugTiming: { getAccessToken_ms: t1 - t0, fetchSheets_ms: t2 - t1, build_ms: t3 - t2, total_ms: t3 - t0 },
          }, corsHeaders);
        } catch (e) {
          return jsonResponse({ status: 'error', message: '讀取投票名單失敗：' + (e && e.message ? e.message : String(e)) }, corsHeaders);
        }
      }

