      if (action === 'stockStatusWorker') return jsonResponse(await doStockStatus_(env), corsHeaders);
      if (action === 'holdingsValueWorker') return jsonResponse(await doHoldingsValue_(env, discordId), corsHeaders);
      if (action === 'stockStateWorker') return jsonResponse(await doStockState_(env, discordId), corsHeaders);
      if (action === 'stockQuoteWorker') return jsonResponse(await doStockQuote_(env, url.searchParams.get('code'), discordId), corsHeaders);
      if (action === 'stockSearchWorker') return jsonResponse(await doStockSearch_(env, url.searchParams.get('q')), corsHeaders);
      if (action === 'stockLeaderboardWorker') return jsonResponse(await doStockLeaderboard_(env, discordId), corsHeaders);
      if (action === 'cryptoPricesWorker') {
        // 輕量報價:不讀試算表,只吃報價快取(同幣種全玩家共用),給前端高頻更新浮動損益用
        const syms = String(url.searchParams.get('symbols') || '').split(',').map((x) => x.trim().toUpperCase()).filter((x) => /^[A-Z0-9]{2,12}$/.test(x)).slice(0, 12);
        if (!syms.length) return jsonResponse({ status: 'success', prices: {}, at: Date.now() }, corsHeaders);
        let qs = {}; try { qs = await cryptoQuotes_(syms, 4000, 60000, 3000); } catch (e) {}
        const prices = {}; for (const c of syms) if (qs[c] && qs[c].price != null) prices[c] = qs[c].price;
        return jsonResponse({ status: 'success', prices, at: Date.now() }, corsHeaders);
      }
