      if (action === 'stockSellWorker') return jsonResponse(await doStockTrade_(env, discordId, 'sell', url.searchParams.get('code'), url.searchParams.get('shares'), ctx), corsHeaders);
      if (action === 'shopInfoCardsWorker') return jsonResponse(await doShopInfoCards_(env, false), corsHeaders);
      if (action === 'infoCardCommentsWorker') return jsonResponse(await doInfoCardComments_(env, discordId, url.searchParams.get('card')), corsHeaders);
      if (action === 'infoCardCommentPostWorker') return jsonResponse(await doInfoCardCommentPost_(env, discordId, url.searchParams.get('card'), url.searchParams.get('text'), url.searchParams.get('parent')), corsHeaders);
      if (action === 'infoCardCommentEditWorker') return jsonResponse(await doInfoCardCommentEdit_(env, discordId, url.searchParams.get('id'), url.searchParams.get('text')), corsHeaders);
      if (action === 'infoCardCommentDeleteWorker') return jsonResponse(await doInfoCardCommentDelete_(env, discordId, url.searchParams.get('id')), corsHeaders);
