          const ts = parseTs(r[0]);
          if (minLive.t && ts && ts >= minLive.t) { skippedLive++; continue; }
          rows.push([ts, toS(r[1]), toS(r[2]), toS(r[3]), toS(r[4]), toS(r[5]), toS(r[6]), toS(r[7]), toS(r[8]), toS(r[9]), toS(r[10]), toS(r[11]), toS(r[12])]);
