          const chunk = rows.slice(i, i + 7);
          const ph = chunk.map(() => "(?,?,?,?,?,?,?,?,?,?,?,?,?,'import')").join(',');
          stmts.push(env.DB.prepare('INSERT INTO history (ts,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10,c11,c12,src) VALUES ' + ph).bind(...chunk.flat()));
