      visibility: row[4] ? row[4].toString() : '',
      showHint: row[5] ? row[5].toString() : '',
      hintText: row[6] ? row[6].toString() : '',
      passwordMode: row[7] ? row[7].toString() : '',
      passwordSeed: row[8] ? row[8].toString() : '',
      passwordSchedule: row[9] ? row[9].toString() : '',
      guessLimitEnabled: row[10] ? row[10].toString() : '',
