        if (foundRow === -1) return { status: 'error', message: '找不到這個模板' };
        const gid = await getSheetIdByName_(token, env.SHEET_ID, T);
        if (gid === null || gid === undefined) return { status: 'unsupported', message: '找不到分頁ID' };
        await deleteSheetRows_(token, env.SHEET_ID, gid, [foundRow]);
        await invalidateTpl();
