        if (foundRow === -1) return { status: 'error', message: '找不到要複製的道具模板' };
        newName = name + '(複製)' + Math.random().toString(36).slice(2, 6).toUpperCase();
        rowValues = Array.from({ length: COLS }, (_, i) => { const v = tsheet[foundRow - 1][i]; return v === undefined || v === null ? '' : v; });
