        let maxOpen = 0;
        if (moRaw) { maxOpen = parseInt(moRaw, 10) || 0; if (maxOpen < 1) return { status: 'error', message: '單次最多開啟數量如果要自訂,至少要是1(留空的話會沿用全站預設值)' }; if (maxOpen > ABSOLUTE_MAX_OPEN_PER_REQUEST_) return { status: 'error', message: '單次最多開啟數量不能超過' + ABSOLUTE_MAX_OPEN_PER_REQUEST_ }; }
        const tf = (v) => v === true || v === 'true' || v === 'TRUE';
        const tradable = tf(body.tradable), reqTrade = tf(body.requireTradeBeforeUse);
        if (reqTrade && !tradable) return { status: 'error', message: '「強迫交易」需要同時開放「可交易」,不然道具發出去之後會卡死,既不能打開也沒辦法透過交易解除限制' };
        const rtcRaw = (body.requireTradeCount === undefined || body.requireTradeCount === null ? '' : body.requireTradeCount).toString().trim();
        let reqTradeCount = 1;
        if (rtcRaw) { reqTradeCount = parseInt(rtcRaw, 10) || 0; if (reqTradeCount < 1) return { status: 'error', message: '「需要交易次數」如果要設定,至少要是1(留空的話預設1次)' }; }
        const tclRaw = (body.tradeCountLimit === undefined || body.tradeCountLimit === null ? '' : body.tradeCountLimit).toString().trim();
        let tradeCountLimit = 0;
