      wrote = true;
      await batchUpdateValues_(token, env.SHEET_ID, [{ range: `'${SH}'!A${ri + 1}:${lastCol}${ri + 1}`, values: [row] }]);
      return await finish({ status: 'success', message: '商品已更新' });
