const CUREXP_CFG_SHEET_ = '貨幣有效期設定', CUREXP_LEDGER_SHEET_ = '貨幣批次', CUREXP_SNAP_SHEET_ = '貨幣對帳', CUREXP_SPEND_SHEET_ = '貨幣消耗', CUREXP_EXC_SHEET_ = '貨幣消耗排除';
