    if (!addRes.ok) throw new Error('建立分頁失敗(' + addRes.status + ')');
    await batchUpdateValues_(accessToken, env.SHEET_ID, missing.map((d) => ({ range: `'${d.name}'!A1`, values: [d.headers] })));
    delete sheetCache['sheetTitles:' + env.SHEET_ID];
