  const defs = [{ name: CURFLOW_LOG_, headers: ['時間(ISO)', 'DiscordID', '貨幣', '變動量(+獲得/−消耗)', '類型(換=貨幣互換,不計入獲得/消耗)'] }, { name: CURFLOW_SNAP_, headers: ['DiscordID', '貨幣', '對帳餘額'] }];
  const existing = await sheetTitlesStrict_(env, accessToken);
