    if (!lock) return { skipped: true };
    const now = Date.now(), nowIso = new Date(now).toISOString();
    const [ledRows, snapRows, playerRows] = await Promise.all([
      fetchOptionalSheet_(accessToken, env.SHEET_ID, CUREXP_LEDGER_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CUREXP_SNAP_SHEET_), fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player),
    ]);
    const led = {}, snap = {};
    for (let i = 1; i < ledRows.length; i++) {
      const r = ledRows[i] || [], id = curExpId_(r[0]), cur = (r[1] || '').toString().trim();
      if (!id || !cur) continue;
      (led[id + '|' + cur] = led[id + '|' + cur] || []).push({ row: i + 1, at: Date.parse((r[2] || '').toString()) || 0, orig: stockNum_(r[3], 0), rem: stockNum_(r[4], 0), reminded: (r[5] || '').toString() === '1', dirty: false });
    }
