  if (!ts && /^\d{8}$/.test(dStr) && /^\d{2}:\d{2}:\d{2}$/.test(tStr)) ts = Date.parse(dStr.slice(0, 4) + '-' + dStr.slice(4, 6) + '-' + dStr.slice(6, 8) + 'T' + tStr + '+08:00') || 0;
