    code: (m.c || '').toString(), name: (m.n || '').toString(), market: (m.ex || '').toString(), price, lastTrade: last, prevClose: prev,
    open: num(m.o), high: num(m.h), low: num(m.l), bid, ask, limitUp: num(m.u), limitDown: num(m.w), volume: num(m.v), date: dStr, time: tStr, ts,
