async function doStockQuote_(env, code, discordId) {
  twSetEnv_(env);
  code = (code || '').toString().trim().toUpperCase();
  if (!/^[0-9A-Z]{4,6}$/.test(code)) return { status: 'error', message: '股票代號格式不對(例:2330、0050)' };
  const accessToken = await getGoogleAccessToken(env);
  const cfg = parseStockConfig_(await getCachedSheetData_('stockCfg:' + env.SHEET_ID, () => stockFetch_(accessToken, env, STOCK_CFG_SHEET_), 30000));
  if (!cfg.enabled || !cfg.currency) return { status: 'error', message: '台股模擬目前沒有開放' };
  if (cfg.whitelist.length && cfg.whitelist.indexOf(code) === -1) return { status: 'error', message: '這檔股票不在開放交易的清單內' };
  let q;
  const wait = stockLookupAllowed_((discordId || '').toString(), code);
  if (wait > 0) return { status: 'error', message: '查太快了,每分鐘最多查 ' + STOCK_LOOKUP_LIMIT_ + ' 檔不同的股票,請 ' + wait + ' 秒後再試' };
  try { q = (await fetchTwQuotes_([code], { ttl: 8000 }))[code]; } catch (e) { return { status: 'error', message: '報價來源暫時無法連線,請稍後再試' }; }
  if (!q) return { status: 'error', message: '查不到「' + code + '」的報價(代號不存在、尚無成交,或來源暫時失敗)' };
  const change = q.prevClose ? stockRound2_(q.price - q.prevClose) : null;
  return { status: 'success', quote: { ...q, delayed: q.source === 'yahoo', change, changePct: q.prevClose ? stockRound2_((q.price - q.prevClose) / q.prevClose * 100) : null, priceCur: stockRound2_(q.price * cfg.rate), isEtf: stockIsEtf_(code) } };
}

async function doStockSearch_(env, qRaw) {
  const q = (qRaw || '').toString().trim().toLowerCase();
  if (!q) return { status: 'success', results: [] };
  const accessToken = await getGoogleAccessToken(env);
  const cfg = parseStockConfig_(await getCachedSheetData_('stockCfg:' + env.SHEET_ID, () => stockFetch_(accessToken, env, STOCK_CFG_SHEET_), 30000));
  const list = await twNameList_get_();
  let res = list.filter((x) => x.code.toLowerCase().startsWith(q) || x.name.toLowerCase().includes(q));
  if (cfg.whitelist.length) res = res.filter((x) => cfg.whitelist.indexOf(x.code) !== -1);
  return { status: 'success', results: res.slice(0, 20), nameListReady: list.length > 0 };
}

function stockCalc_(cfg, code, price, shares, side) {
  const gross = price * shares; // TWD
  const fee = Math.max(cfg.feeMin, gross * cfg.feeRate);
  const tax = side === 'sell' ? gross * (stockIsEtf_(code) ? cfg.etfTaxRate : cfg.taxRate) : 0;
  return { gross, fee, tax };
}

async function doStockTrade_(env, discordId, side, codeRaw, sharesRaw, ctx, amountRaw) {
  const code = (codeRaw || '').toString().trim().toUpperCase();
  // 🌟🆕 依金額買進:amount=要花多少遊戲貨幣,股數在成交當下依即時報價自動換算(整股、含手續費、不超過這個金額)
  const byAmount = side === 'buy' && parseFloat(amountRaw) > 0;
  const amountBudget = byAmount ? parseFloat(amountRaw) : 0;
  let shares = byAmount ? 1 : parseInt(sharesRaw, 10);
  if (!/^[0-9A-Z]{4,6}$/.test(code)) return { status: 'error', safeNoWrite: true, message: '股票代號格式不對' };
  if (!(shares >= 1)) return { status: 'error', safeNoWrite: true, message: '股數至少要1股' };
  return stockWithLock_(env, discordId, async (accessToken, mark) => {
    const [cfgRows, posRows0, playerRows] = await Promise.all([
      stockFetch_(accessToken, env, STOCK_CFG_SHEET_),
      fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_POS_SHEET_),
      fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player),
    ]);
    const cfg = parseStockConfig_(cfgRows);
    if (!cfg.enabled || !cfg.currency) return { status: 'error', safeNoWrite: true, message: '台股模擬目前沒有開放' };
    if (cfg.whitelist.length && cfg.whitelist.indexOf(code) === -1) return { status: 'error', safeNoWrite: true, message: '這檔股票不在開放交易的清單內' };
    if (!byAmount && cfg.maxShares > 0 && shares > cfg.maxShares) return { status: 'error', safeNoWrite: true, message: '單筆最多只能交易 ' + cfg.maxShares + ' 股' };
    const market = await stockMarketStatus_(cfg);
    if (!market.open) return { status: 'error', safeNoWrite: true, message: market.message || '目前不能交易' };
    let q;
    try { q = (await fetchTwQuotes_([code]))[code]; } catch (e) { q = null; }
    if (!q) return { status: 'error', safeNoWrite: true, message: '抓不到「' + code + '」的即時報價,請稍後再試' };
    if (q.source === 'yahoo' && !cfg.allowDelayed) return { status: 'error', safeNoWrite: true, message: '目前即時報價來源無法使用,只剩延遲約20分鐘的報價,為避免價差套利暫停交易,請稍後再試' };
    const hdr = playerRows[0] || [];
    const ci = hdr.indexOf(cfg.currency);
    let prow = -1;
    for (let p = 1; p < playerRows.length; p++) if (playerRows[p][0] && playerRows[p][0].toString().replace("'", '') === discordId.toString()) { prow = p + 1; break; }
    if (ci === -1 || prow === -1) return { status: 'error', safeNoWrite: true, message: '找不到你的貨幣資料(貨幣欄位:' + cfg.currency + '),請聯絡管理員' };
    const before = stockNum_(playerRows[prow - 1][ci], 0);
    const disp = getDisplayCurrencyName(cfg.currency);
    if (byAmount) {
      const buyCostOf = (n) => { const g = q.price * n; return stockCeil2_((g + Math.max(cfg.feeMin, g * cfg.feeRate)) * cfg.rate); };
      shares = Math.floor((amountBudget / cfg.rate) / (q.price * (1 + cfg.feeRate)));
      if (cfg.maxShares > 0 && shares > cfg.maxShares) shares = cfg.maxShares;
      while (shares >= 1 && buyCostOf(shares) > amountBudget) shares--;
      if (shares < 1) return { status: 'error', safeNoWrite: true, message: '金額不夠買 1 股「' + code + '」(現價 ' + q.price + ' TWD,買 1 股約需 ' + buyCostOf(1) + ' ' + disp + ')' };
    }
    const c = stockCalc_(cfg, code, q.price, shares, side);
    const mine = stockPosOf_(posRows0, discordId);
    let pos = mine.find((p) => p.code === code);
    const nowIso = new Date().toISOString();
    const playerCell = `'${SHEET_NAMES.player}'!${colToA1_(ci)}${prow}`;
    const sendHook = (x) => { if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(queueWebhookWorker_(x)); else queueWebhookWorker_(x); };
    const safe_ = (x) => (x || '').toString().replace(/[|,:;=@%]/g, '、');
    const reason = '台股' + (side === 'buy' ? '買進' : '賣出') + '：' + q.name + '(' + code + ')';
    if (side === 'buy') {
      const cost = stockCeil2_((c.gross + c.fee) * cfg.rate);
      if (before < cost) return { status: 'error', safeNoWrite: true, message: disp + '不足:買進 ' + shares + ' 股需要約 ' + cost + ',你目前只有 ' + before };
      mark();
      if (!pos) {
        await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, STOCK_POS_SHEET_, 'stockPos', [["'" + discordId, code, q.name, 0, 0, nowIso]]);
        const fresh = await fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_POS_SHEET_);
        pos = stockPosOf_(fresh, discordId).filter((p) => p.code === code).pop();
        if (!pos) throw new Error('建立持倉資料失敗,請重試(尚未扣款)');
      }
      const newShares = pos.shares + shares, newCost = stockRound2_(pos.cost + cost);
      await batchUpdateValues_(accessToken, env.SHEET_ID, [
        { range: playerCell, values: [[stockRound2_(before - cost)]] },
        { range: `'${STOCK_POS_SHEET_}'!C${pos.rowIdx}:F${pos.rowIdx}`, values: [[q.name, newShares, newCost, nowIso]] },
      ]);
      invalidateCraftCaches_(env, ['player']);
      try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, STOCK_LOG_SHEET_, 'stockLog', [[nowIso, "'" + discordId, code, q.name, '買進', shares, q.price, cost, stockRound2_(c.fee * cfg.rate), 0, '', stockRound2_(before - cost), cfg.currency]]); } catch (e) {}
      try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), discordId.toString(), '[台股買進] ' + q.name + '(' + code + ')', shares, '', '', '以 ' + q.price + ' 買進 ' + shares + ' 股,花費 ' + cost + ' ' + disp, '', '']); } catch (e) {}
      sendHook('[貨幣調整批次] ' + safe_(reason) + '|' + discordId + '@- ' + safe_(disp) + ' -' + cost + '|' + cfg.currency + ':' + discordId + ':' + (-cost) + '|SILENT');
      return { status: 'success', side, code, name: q.name, shares, price: q.price, amount: cost, fee: stockRound2_(c.fee * cfg.rate), balance: stockRound2_(before - cost), message: '✅ 買進 ' + q.name + '(' + code + ') ' + shares + ' 股,成交價 ' + q.price + ',花費 ' + cost + ' ' + disp };
    }
    // 賣出
    if (!pos || pos.shares < shares) return { status: 'error', safeNoWrite: true, message: '你只持有 ' + (pos ? pos.shares : 0) + ' 股「' + code + '」,不夠賣 ' + shares + ' 股' };
    const proceeds = stockFloor2_((c.gross - c.fee - c.tax) * cfg.rate);
    const costBasis = stockRound2_(pos.cost * shares / pos.shares);
    const pnl = stockRound2_(proceeds - costBasis);
    const newShares = pos.shares - shares, newCost = newShares > 0 ? stockRound2_(pos.cost - costBasis) : 0;
    mark();
    await batchUpdateValues_(accessToken, env.SHEET_ID, [
      { range: playerCell, values: [[stockRound2_(before + proceeds)]] },
      { range: `'${STOCK_POS_SHEET_}'!D${pos.rowIdx}:F${pos.rowIdx}`, values: [[newShares, newCost, nowIso]] },
    ]);
    invalidateCraftCaches_(env, ['player']);
    try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, STOCK_LOG_SHEET_, 'stockLog', [[nowIso, "'" + discordId, code, q.name || pos.name, '賣出', shares, q.price, proceeds, stockRound2_(c.fee * cfg.rate), stockRound2_(c.tax * cfg.rate), pnl, stockRound2_(before + proceeds), cfg.currency]]); } catch (e) {}
    try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), discordId.toString(), '[台股賣出] ' + (q.name || pos.name) + '(' + code + ')', shares, '', '', '以 ' + q.price + ' 賣出 ' + shares + ' 股,獲得 ' + proceeds + ' ' + disp + '(損益 ' + pnl + ')', '', '']); } catch (e) {}
    sendHook('[貨幣調整批次] ' + safe_(reason) + '|' + discordId + '@+ ' + safe_(disp) + ' +' + proceeds + '|' + cfg.currency + ':' + discordId + ':' + proceeds + '|SILENT');
    return { status: 'success', side, code, name: q.name || pos.name, shares, price: q.price, amount: proceeds, fee: stockRound2_(c.fee * cfg.rate), tax: stockRound2_(c.tax * cfg.rate), pnl, balance: stockRound2_(before + proceeds), message: '✅ 賣出 ' + (q.name || pos.name) + '(' + code + ') ' + shares + ' 股,成交價 ' + q.price + ',獲得 ' + proceeds + ' ' + disp + '(損益 ' + (pnl >= 0 ? '+' : '') + pnl + ')' };
  });
}

let stockLbMemo_ = { at: 0, data: null };
// 排行榜:玩家的「總損益」(已實現+未實現)與「總資產」(貨幣餘額+持股市值)。20秒共用快取(股票持股報價用60秒內的,省額度)。
async function doStockLeaderboard_(env, discordId) {
  twSetEnv_(env);
  if (!stockLbMemo_.data || Date.now() - stockLbMemo_.at > 20000) {
    const accessToken = await getGoogleAccessToken(env);
    await ensureStockSheets_(env, accessToken);
    const [cfgRows, posRows, logRows, playerRows, levRowsAll] = await Promise.all([
      stockFetch_(accessToken, env, STOCK_CFG_SHEET_),
      fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_POS_SHEET_),
      fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_LOG_SHEET_),
      fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player),
      fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_LEV_SHEET_),
    ]);
    const cfg = parseStockConfig_(cfgRows), lcS = stockLevCfg_(cfgRows);
    if (!cfg.enabled || !cfg.currency) return { status: 'success', enabled: false };
    const idOf = (v) => (v || '').toString().replace("'", '');
    const players = {};
    const get = (id) => (players[id] = players[id] || { id, realized: 0, cost: 0, value: 0, holdCount: 0, trades: 0 });
    for (let i = 1; i < logRows.length; i++) { const r = logRows[i]; const id = idOf(r[1]); if (!id) continue; if (((r[12] || '').toString().trim() || cfg.currency) !== cfg.currency) continue; const pl = get(id); pl.trades++; if (['賣出', '平倉', '強平'].indexOf((r[4] || '').toString()) !== -1) pl.realized += stockNum_(r[10], 0); }
    const holds = [];
    for (let i = 1; i < posRows.length; i++) { const r = posRows[i]; const id = idOf(r[0]); const sh = parseInt(r[3], 10) || 0; if (!id || sh <= 0) continue; holds.push({ id, code: (r[1] || '').toString(), shares: sh, cost: stockNum_(r[4], 0) }); get(id); }
    const levAllS = levPosParse_(levRowsAll);
    levAllS.forEach((p) => get(p.discordId));
    const codes = Array.from(new Set(holds.map((h) => h.code).concat(levAllS.map((p) => p.symbol)))).slice(0, 25);
    let quotes = {}; try { quotes = await fetchTwQuotes_(codes, { ttl: 60000, relayOk: true }); } catch (e) {}
    levAllS.forEach((p) => { const pl = get(p.discordId); const q = quotes[p.symbol]; pl.cost += p.margin + p.openFee; pl.holdCount++; pl.value += q ? stockLevEval_(p, q.price, cfg, lcS).equity : p.margin; });
    holds.forEach((h) => { const pl = get(h.id); const q = quotes[h.code]; pl.cost += h.cost; pl.holdCount++; pl.value += q ? stockFloor2_(q.price * cfg.rate * h.shares) : h.cost; });
    const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
    const info = {};
    for (let i = 1; i < playerRows.length; i++) { const id = idOf(playerRows[i][0]); if (id && players[id]) info[id] = { name: (playerRows[i][1] || '').toString(), bal: ci === -1 ? 0 : stockNum_(playerRows[i][ci], 0) }; }
    const list = Object.values(players).map((pl) => { const inf = info[pl.id] || { name: '(未知)', bal: 0 }; return { id: pl.id, name: inf.name, pnl: stockRound2_(pl.realized + (pl.value - pl.cost)), realized: stockRound2_(pl.realized), unreal: stockRound2_(pl.value - pl.cost), assets: stockRound2_(inf.bal + pl.value), holdCount: pl.holdCount, trades: pl.trades }; });
    stockLbMemo_ = { at: Date.now(), data: { list, currencyDisplay: getDisplayCurrencyName(cfg.currency), live: !Object.values(quotes).some((q) => q && q.source === 'yahoo') } };
  }
  const d = stockLbMemo_.data;
  const rank = (key) => {
    const sorted = d.list.slice().sort((a, b) => b[key] - a[key]);
    const my = sorted.findIndex((x) => x.id === discordId.toString());
    return { top: sorted.slice(0, 20).map((x, i) => ({ rank: i + 1, name: x.name, value: x[key], holdCount: x.holdCount, trades: x.trades, me: x.id === discordId.toString() })), me: my === -1 ? null : { rank: my + 1, value: sorted[my][key] }, total: sorted.length };
  };
  return { status: 'success', enabled: true, currencyDisplay: d.currencyDisplay, delayed: !d.live, updatedAt: stockLbMemo_.at, pnl: rank('pnl'), assets: rank('assets'), realized: rank('realized'), unreal: rank('unreal') };
}


// ============================================================
// 📈 台股槓桿(合約式,做多/做空,保證金制,自動強平;不能留倉過夜,收盤前自動平倉)
// 設定寫在「股票設定」分頁底部:槓桿啟用/最大倍數/強平虧損比例/最低保證金/單人最大持倉數/強平私訊通知/收盤前自動平倉分鐘
// ============================================================
function stockLevCfg_(rows) {
  const lc = cryptoLevCfg_(rows);
  let m = 5;
  for (let i = 1; i < (rows || []).length; i++) if (rows[i] && (rows[i][0] || '').toString().trim() === '收盤前自動平倉分鐘') m = Math.max(0, Math.min(120, Math.floor(stockNum_(rows[i][1], 5))));
  lc.autoCloseMin = m;
  return lc;
}
// 現在是不是「收盤前自動平倉」區間(任一開放時段結束前 N 分鐘內)
function stockInAutoCloseZone_(cfg, lc) {
  const n = twNow_();
  return cfg.windows.some((w) => n.min >= w.e - lc.autoCloseMin && n.min < w.e);
}
function stockLevEval_(p, price, cfg, lc) {
  const pnl = (p.side === '多' ? price - p.entry : p.entry - price) * p.qty * cfg.rate;
  const gross = p.qty * price;
  const feeOnly = Math.max(cfg.feeMin, gross * cfg.feeRate) * cfg.rate;
  const tax = gross * (stockIsEtf_(p.symbol) ? cfg.etfTaxRate : cfg.taxRate) * cfg.rate;
  const closeFee = feeOnly + tax;
  const liqPrice = p.side === '多' ? p.entry * (1 - lc.liqRatio / p.lev) : p.entry * (1 + lc.liqRatio / p.lev);
  return { pnl: stockRound2_(pnl), equity: stockRound2_(Math.max(0, p.margin + pnl)), feeOnly, tax, closeFee, liqPrice, liq: pnl <= -p.margin * lc.liqRatio + 1e-9, payout: stockFloor2_(Math.max(0, p.margin + pnl - closeFee)) };
}
// kind: 'close'(手動平倉) / 'liq'(強平) / 'auto'(收盤前自動平倉)
async function stockLevCloseCore_(env, accessToken, mark, cfg, lc, pos, q, kind, ctx) {
  const price = q.price;
  const playerRows = await fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player);
  const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
  let prow = -1;
  for (let i = 1; i < playerRows.length; i++) if (playerRows[i][0] && playerRows[i][0].toString().replace("'", '') === pos.discordId) { prow = i + 1; break; }
  if (ci === -1 || prow === -1) throw new Error('找不到玩家貨幣資料');
  const before = stockNum_(playerRows[prow - 1][ci], 0);
  const ev = stockLevEval_(pos, price, cfg, lc);
  const payout = ev.payout;
  const pnl = stockRound2_(payout - pos.margin - pos.openFee);
  const disp = getDisplayCurrencyName(cfg.currency);
  const nowIso = new Date().toISOString();
  mark();
  await batchUpdateValues_(accessToken, env.SHEET_ID, [
    { range: `'${SHEET_NAMES.player}'!${colToA1_(ci)}${prow}`, values: [[stockRound2_(before + payout)]] },
    { range: `'${STOCK_LEV_SHEET_}'!A${pos.rowIdx}:J${pos.rowIdx}`, values: [['', '', '', '', '', '', '', '', '', '']] },
  ]);
  invalidateCraftCaches_(env, ['player']);
  const label = q.name || pos.symbol;
  const act = kind === 'liq' ? '強平' : '平倉';
  const nm = label + '(' + pos.symbol + ' ' + pos.side + 'x' + pos.lev + ')';
  try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, STOCK_LOG_SHEET_, 'stockLog', [[nowIso, "'" + pos.discordId, pos.symbol, label + '(' + pos.side + 'x' + pos.lev + ')', act, pos.qty, price, payout, stockRound2_(ev.feeOnly), stockRound2_(ev.tax), pnl, stockRound2_(before + payout), cfg.currency]]); } catch (e) {}
  const actLabel = kind === 'liq' ? '強平' : (kind === 'auto' ? '收盤自動平倉' : '平倉');
  try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), pos.discordId, '[台股槓桿' + actLabel + '] ' + nm, pos.qty, '', '', '以 ' + price + ' TWD ' + actLabel + ',返還 ' + payout + ' ' + disp + '(損益 ' + pnl + ')', '', '']); } catch (e) {}
  if (payout > 0) {
    levSendHook_(ctx, '[貨幣調整批次] ' + levSafe_('台股槓桿' + actLabel + '：' + nm) + '|' + pos.discordId + '@+ ' + levSafe_(disp) + ' +' + payout + '|' + cfg.currency + ':' + pos.discordId + ':' + payout + '|SILENT');
  }
  {
    const ttl = kind === 'liq' ? '⚠️ 台股槓桿強平' : (kind === 'auto' ? '🔔 台股槓桿收盤自動平倉' : '✅ 台股槓桿平倉');
    await levNotifyTrade_(env, ctx, lc, pos.discordId, ttl, actLabel + ' ' + nm + ' 成交價 ' + price + ' TWD 損益 ' + pnl + ' ' + disp + (payout > 0 ? ' 返還 ' + payout : ' 保證金全賠未返還'));
  }
  return { payout, pnl, balance: stockRound2_(before + payout), kind, symbol: pos.symbol, side: pos.side, lev: pos.lev, price };
}
async function doStockLevOpen_(env, discordId, codeRaw, sideRaw, levRaw, marginRaw, ctx) {
  const code = (codeRaw || '').toString().trim().toUpperCase();
  const side = sideRaw === 'short' || sideRaw === '空' ? '空' : (sideRaw === 'long' || sideRaw === '多' ? '多' : '');
  const lev = Math.floor(parseFloat(levRaw));
  const margin = stockFloor2_(parseFloat(marginRaw) || 0);
  if (!/^[0-9A-Z]{4,6}$/.test(code)) return { status: 'error', safeNoWrite: true, message: '股票代號格式不對' };
  if (!side) return { status: 'error', safeNoWrite: true, message: '請選擇做多或做空' };
  if (!(lev >= 1)) return { status: 'error', safeNoWrite: true, message: '倍數至少要1倍' };
  if (!(margin > 0)) return { status: 'error', safeNoWrite: true, message: '保證金要大於0' };
  return stockWithLock_(env, discordId, async (accessToken, mark) => {
    const [cfgRows, levRows, playerRows] = await Promise.all([stockFetch_(accessToken, env, STOCK_CFG_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_LEV_SHEET_), fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player)]);
    const cfg = parseStockConfig_(cfgRows), lc = stockLevCfg_(cfgRows);
    if (!cfg.enabled || !cfg.currency) return { status: 'error', safeNoWrite: true, message: '台股模擬目前沒有開放' };
    if (!lc.enabled) return { status: 'error', safeNoWrite: true, message: '台股槓桿目前沒有開放' };
    if (cfg.whitelist.length && cfg.whitelist.indexOf(code) === -1) return { status: 'error', safeNoWrite: true, message: '這檔股票不在開放交易的清單內' };
    const market = await stockMarketStatus_(cfg);
    if (!market.open) return { status: 'error', safeNoWrite: true, message: market.message || '目前不能交易' };
    if (lc.autoCloseMin > 0 && stockInAutoCloseZone_(cfg, lc)) return { status: 'error', safeNoWrite: true, message: '已進入收盤前 ' + lc.autoCloseMin + ' 分鐘,槓桿不能再開倉(槓桿倉位不留過夜,會在收盤前自動平倉)' };
    if (lev > lc.maxLev) return { status: 'error', safeNoWrite: true, message: '最大只能開到 ' + lc.maxLev + ' 倍' };
    if (margin < lc.minMargin) return { status: 'error', safeNoWrite: true, message: '保證金最少要 ' + lc.minMargin };
    const mine = levPosParse_(levRows).filter((p) => p.discordId === discordId.toString());
    if (mine.length >= lc.maxPositions) return { status: 'error', safeNoWrite: true, message: '最多同時持有 ' + lc.maxPositions + ' 個槓桿倉位,請先平倉' };
    let q;
    try { q = (await fetchTwQuotes_([code]))[code]; } catch (e) { q = null; }
    if (!q) return { status: 'error', safeNoWrite: true, message: '抓不到「' + code + '」的即時報價,請稍後再試' };
    if (q.source === 'yahoo' && !cfg.allowDelayed) return { status: 'error', safeNoWrite: true, message: '目前即時報價來源無法使用,只剩延遲報價,為避免價差套利暫停交易,請稍後再試' };
    const notional = margin * lev;
    const qty = Math.floor(notional / (cfg.rate * q.price) * 1e4 + 1e-6) / 1e4;
    if (!(qty > 0)) return { status: 'error', safeNoWrite: true, message: '金額太小,請提高保證金' };
    if (cfg.maxShares > 0 && qty > cfg.maxShares) return { status: 'error', safeNoWrite: true, message: '單筆倉位最多 ' + cfg.maxShares + ' 股' };
    const gross = qty * q.price;
    const openFee = stockCeil2_(Math.max(cfg.feeMin, gross * cfg.feeRate) * cfg.rate);
    const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
    let prow = -1;
    for (let i = 1; i < playerRows.length; i++) if (playerRows[i][0] && playerRows[i][0].toString().replace("'", '') === discordId.toString()) { prow = i + 1; break; }
    if (ci === -1 || prow === -1) return { status: 'error', safeNoWrite: true, message: '找不到你的貨幣資料(貨幣欄位:' + cfg.currency + '),請聯絡管理員' };
    const before = stockNum_(playerRows[prow - 1][ci], 0);
    const disp = getDisplayCurrencyName(cfg.currency);
    const total = stockRound2_(margin + openFee);
    if (before < total) return { status: 'error', safeNoWrite: true, message: disp + '不足:保證金 ' + margin + ' + 手續費 ' + openFee + ' = ' + total + ',你目前只有 ' + before };
    const posId = 'S' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const nowIso = new Date().toISOString();
    mark();
    await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, STOCK_LEV_SHEET_, 'stockLev', [[posId, "'" + discordId, code, side, lev, 0, q.price, 0, 0, nowIso]]);
    const fresh = levPosParseRaw_(await fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_LEV_SHEET_), posId);
    if (!fresh) throw new Error('建立倉位資料失敗,請重試(尚未扣款)');
    await batchUpdateValues_(accessToken, env.SHEET_ID, [
      { range: `'${SHEET_NAMES.player}'!${colToA1_(ci)}${prow}`, values: [[stockRound2_(before - total)]] },
      { range: `'${STOCK_LEV_SHEET_}'!A${fresh}:J${fresh}`, values: [[posId, "'" + discordId, code, side, lev, margin, q.price, qty, openFee, nowIso]] },
    ]);
    invalidateCraftCaches_(env, ['player']);
    const label = q.name || code;
    const nm = label + '(' + code + ' ' + side + 'x' + lev + ')';
    try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, STOCK_LOG_SHEET_, 'stockLog', [[nowIso, "'" + discordId, code, label + '(' + side + 'x' + lev + ')', '開倉', qty, q.price, margin, openFee, 0, '', stockRound2_(before - total), cfg.currency]]); } catch (e) {}
    try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), discordId.toString(), '[台股槓桿開倉] ' + nm, qty, '', '', '以 ' + q.price + ' TWD 開倉,保證金 ' + margin + ' ' + disp + ',手續費 ' + openFee, '', '']); } catch (e) {}
    levSendHook_(ctx, '[貨幣調整批次] ' + levSafe_('台股槓桿開倉：' + nm) + '|' + discordId + '@- ' + levSafe_(disp) + ' -' + total + '|' + cfg.currency + ':' + discordId + ':' + (-total) + '|SILENT');
    const liqPrice = side === '多' ? q.price * (1 - lc.liqRatio / lev) : q.price * (1 + lc.liqRatio / lev);
    await levNotifyTrade_(env, ctx, lc, discordId, '📈 台股槓桿開倉', '開倉 ' + nm + ' 成交價 ' + q.price + ' TWD 保證金 ' + margin + ' ' + disp + ' 強平價約 ' + (Math.round(liqPrice * 100) / 100) + ' TWD');
    return { status: 'success', symbol: code, side, lev, margin, price: q.price, qty, openFee, liqPrice, balance: stockRound2_(before - total), message: '✅ 開倉 ' + label + ' ' + side + ' ' + lev + ' 倍,開倉價 ' + q.price + ' TWD,保證金 ' + margin + ' ' + disp + '(手續費 ' + openFee + '),強平價約 ' + stockRound2_(liqPrice) + ' TWD(槓桿倉位不留過夜,收盤前會自動平倉)' };
  });
}
async function doStockLevClose_(env, discordId, posId, ctx) {
  posId = (posId || '').toString();
  if (!posId) return { status: 'error', safeNoWrite: true, message: '缺少倉位ID' };
  return stockWithLock_(env, discordId, async (accessToken, mark) => {
    const [cfgRows, levRows] = await Promise.all([stockFetch_(accessToken, env, STOCK_CFG_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_LEV_SHEET_)]);
    const cfg = parseStockConfig_(cfgRows), lc = stockLevCfg_(cfgRows);
    if (!cfg.currency) return { status: 'error', safeNoWrite: true, message: '台股設定尚未完成' };
    const pos = levPosParse_(levRows).find((p) => p.id === posId && p.discordId === discordId.toString());
    if (!pos) return { status: 'error', safeNoWrite: true, message: '找不到這個倉位(可能已經平倉或被強平)' };
    let q;
    try { q = (await fetchTwQuotes_([pos.symbol]))[pos.symbol]; } catch (e) { q = null; }
    if (!q) return { status: 'error', safeNoWrite: true, message: '抓不到即時報價,請稍後再試' };
    const ev = stockLevEval_(pos, q.price, cfg, lc);
    const r = await stockLevCloseCore_(env, accessToken, mark, cfg, lc, pos, q, ev.liq ? 'liq' : 'close', ctx);
    const disp = getDisplayCurrencyName(cfg.currency);
    return { status: 'success', ...r, message: (ev.liq ? '⚠️ 這個倉位已達強平條件,已強制平倉,' : '✅ 已平倉,') + '成交價 ' + q.price + ' TWD,返還 ' + r.payout + ' ' + disp + '(損益 ' + (r.pnl >= 0 ? '+' : '') + r.pnl + ')' };
  });
}
// 每分鐘由排程呼叫:達強平條件 / 收盤前 / 已收盤 的台股槓桿倉位自動平倉
async function runStockLevScan_(env, ctx) {
  twSetEnv_(env);
  const accessToken = await getGoogleAccessToken(env);
  const positions = levPosParse_(await fetchOptionalSheet_(accessToken, env.SHEET_ID, STOCK_LEV_SHEET_));
  if (!positions.length) return;
  const cfgRows = await stockFetch_(accessToken, env, STOCK_CFG_SHEET_);
  const cfg = parseStockConfig_(cfgRows), lc = stockLevCfg_(cfgRows);
  if (!cfg.currency) return;
  // 收盤前N分鐘、或已經不在開放時段(含休市/停用)→ 一律平倉,不留過夜
  let force = !cfg.enabled || stockInAutoCloseZone_(cfg, lc);
  if (!force) { const w = stockWindowOpen_(cfg); if (!w.open) force = true; }
  let quotes = {};
  try { quotes = await fetchTwQuotes_(Array.from(new Set(positions.map((p) => p.symbol))).slice(0, 40), { ttl: 5000 }); } catch (e) {}
  const hit = positions.filter((p) => { const q = quotes[p.symbol]; return q && (force || stockLevEval_(p, q.price, cfg, lc).liq); }).slice(0, 10);
  for (const p of hit) {
    try {
      await stockWithLock_(env, p.discordId, async (at, mark) => {
        const fresh = levPosParse_(await fetchOptionalSheet_(at, env.SHEET_ID, STOCK_LEV_SHEET_)).find((x) => x.id === p.id);
        if (!fresh) return { status: 'success' };
        let q; try { q = (await fetchTwQuotes_([fresh.symbol], { ttl: 3000 }))[fresh.symbol]; } catch (e) { q = null; }
        if (!q) return { status: 'success' };
        const liq = stockLevEval_(fresh, q.price, cfg, lc).liq;
        if (!force && !liq) return { status: 'success' };
        await stockLevCloseCore_(env, at, mark, cfg, lc, fresh, q, liq ? 'liq' : 'auto', ctx);
        return { status: 'success' };
      });
    } catch (e) { console.error('台股槓桿巡邏失敗:', e && e.message ? e.message : e); }
  }
}

// ============================================================
// ₿ 加密貨幣虛擬交易(Worker專屬)。24小時可交易(後台可限制日期/星期/時段),市價單,數量可到小數8位。
// 分頁(自動建立):加密設定(key/value,格式同股票設定)、加密持倉、加密交易紀錄。
// 報價:Coinbase公開行情(主)→Binance(備用),以美元(USD/USDT)計價,再乘匯率換成遊戲貨幣。
// ============================================================
const CRYPTO_CFG_SHEET_ = '加密設定';
const CRYPTO_POS_SHEET_ = '加密持倉';
const CRYPTO_LOG_SHEET_ = '加密交易紀錄';
const CRYPTO_LEV_SHEET_ = '加密槓桿持倉';
const CRYPTO_DEFAULT_LIST_ = 'BTC,ETH,SOL,BNB,XRP,DOGE,ADA,LTC';
const CRYPTO_SHEETS_DEF_ = [
  { name: CRYPTO_CFG_SHEET_, headers: ['設定', '值'], rows: [['啟用', 'FALSE'], ['貨幣', ''], ['匯率', '30'], ['手續費率', '0.001'], ['手續費最低', '0'], ['證交稅率', '0'], ['ETF證交稅率', '0'], ['開放日期起', ''], ['開放日期迄', ''], ['下單日期起', ''], ['下單日期迄', ''], ['開放星期', '1,2,3,4,5,6,7'], ['開放時段', '00:00-24:00'], ['標的白名單', CRYPTO_DEFAULT_LIST_], ['單筆最大股數', ''], ['允許延遲報價交易', 'FALSE'], ['槓桿啟用', 'FALSE'], ['最大倍數', '10'], ['強平虧損比例', '0.9'], ['最低保證金', '1'], ['單人最大持倉數', '5'], ['強平私訊通知', 'TRUE']] },
  { name: CRYPTO_LEV_SHEET_, headers: ['倉位ID', 'DiscordID', '代號', '方向', '槓桿', '保證金(貨幣)', '開倉價(USD)', '數量', '開倉手續費(貨幣)', '開倉時間'] },
  { name: CRYPTO_POS_SHEET_, headers: ['DiscordID', '代號', '名稱', '數量', '總成本(貨幣)', '更新時間'] },
  { name: CRYPTO_LOG_SHEET_, headers: ['時間', 'DiscordID', '代號', '名稱', '動作', '數量', '成交價(USD)', '金額(貨幣)', '手續費(貨幣)', '已實現損益(貨幣)', '交易後餘額', '貨幣'] },
];
const CRYPTO_NAMES_ = { BTC: '比特幣', ETH: '以太幣', SOL: 'Solana', BNB: '幣安幣', XRP: '瑞波幣', DOGE: '狗狗幣', ADA: '艾達幣', LTC: '萊特幣', DOT: '波卡', AVAX: 'Avalanche', LINK: 'Chainlink', MATIC: 'Polygon', TRX: '波場幣', SHIB: '柴犬幣', USDT: '泰達幣' };
const CRYPTO_TTL_MS_ = 10000;
const cryptoMem_ = {};
const cryptoInflight_ = {};

async function ensureCryptoSheets_(env, accessToken) {
  const key = 'cryptoEnsured:' + env.SHEET_ID;
  if (sheetCache[key]) return;
  const existing = await sheetTitlesStrict_(env, accessToken);
  const missing = CRYPTO_SHEETS_DEF_.filter((d) => existing.indexOf(d.name) === -1);
  if (missing.length > 0) {
    const addRes = await fetchWithTimeout_(`https://sheets.googleapis.com/v4/spreadsheets/${env.SHEET_ID}:batchUpdate`, { method: 'POST', headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ requests: missing.map((d) => ({ addSheet: { properties: { title: d.name } } })) }) });
    if (!addRes.ok) throw new Error('建立分頁失敗(' + addRes.status + ')');
    await batchUpdateValues_(accessToken, env.SHEET_ID, missing.map((d) => ({ range: `'${d.name}'!A1`, values: [d.headers].concat(d.rows || []) })));
    delete sheetCache['sheetTitles:' + env.SHEET_ID];
  }
  sheetCache[key] = true;
}
async function cryptoFetch_(accessToken, env, name) {
  let rows = await fetchOptionalSheet_(accessToken, env.SHEET_ID, name);
  if (rows.length === 0) { delete sheetCache['sheetTitles:' + env.SHEET_ID]; rows = await fetchOptionalSheet_(accessToken, env.SHEET_ID, name); }
  return rows;
}
function parseCryptoConfig_(rows) {
  const c = parseStockConfig_(rows);
  if (!c.whitelist.length) c.whitelist = CRYPTO_DEFAULT_LIST_.split(',');
  c.whitelist = c.whitelist.map((x) => x.toUpperCase());
  return c;
}
function cryptoQty_(v) { const n = parseFloat((v === undefined || v === null ? '' : v).toString()); return isNaN(n) ? 0 : Math.floor(n * 1e8 + 1e-6) / 1e8; }

// Coinbase 公開API每秒約10次;多幣種同時查會被限流,所以:行情(ticker)併發最多3個、24小時統計(stats)快取5分鐘
let cryptoCbActive_ = 0;
const cryptoCbWait_ = [];
async function cryptoCbSlot_(fn) {
  while (cryptoCbActive_ >= 3) await new Promise((r) => cryptoCbWait_.push(r));
  cryptoCbActive_++;
  try { return await fn(); } finally { cryptoCbActive_--; const n = cryptoCbWait_.shift(); if (n) n(); }
}
async function cryptoCbGet_(url) {
  const ua = { 'User-Agent': TW_UA_, 'Accept': 'application/json' };
  for (let k = 0; k < 2; k++) {
    const res = await cryptoCbSlot_(() => fetchWithTimeout_(url, { headers: ua }, 5000));
    if (res.status === 429) { await new Promise((r) => setTimeout(r, 400)); continue; }
    return res;
  }
  return null;
}
const cryptoStats_ = {};
async function cryptoOne_(sym) {
  const ua = { 'User-Agent': TW_UA_, 'Accept': 'application/json' };
  const num = (v) => { const n = parseFloat(v); return isNaN(n) ? null : n; };
  try {
    const t = await cryptoCbGet_('https://api.exchange.coinbase.com/products/' + sym + '-USD/ticker');
    if (t && t.ok) {
      const tj = await t.json();
      const price = num(tj.price);
      if (price > 0) {
        let sj = (cryptoStats_[sym] && Date.now() - cryptoStats_[sym].at < 300000) ? cryptoStats_[sym].v : null;
        if (!sj) { try { const st = await cryptoCbGet_('https://api.exchange.coinbase.com/products/' + sym + '-USD/stats'); sj = st && st.ok ? await st.json() : (cryptoStats_[sym] ? cryptoStats_[sym].v : {}); cryptoStats_[sym] = { at: Date.now(), v: sj }; } catch (e) { sj = {}; } }
        const open = num(sj.open);
        return { symbol: sym, name: CRYPTO_NAMES_[sym] || sym, price, open, high: num(sj.high), low: num(sj.low), volume: num(sj.volume), change: open ? price - open : null, changePct: open ? (price - open) / open * 100 : null, ts: Date.parse(tj.time) || Date.now(), source: 'coinbase' };
      }
    }
  } catch (e) {}
  try {
    const res = await fetchWithTimeout_('https://api.binance.com/api/v3/ticker/24hr?symbol=' + sym + 'USDT', { headers: ua }, 5000);
    if (res.ok) {
      const j = await res.json(); const price = num(j.lastPrice);
      if (price > 0) return { symbol: sym, name: CRYPTO_NAMES_[sym] || sym, price, open: num(j.openPrice), high: num(j.highPrice), low: num(j.lowPrice), volume: num(j.volume), change: num(j.priceChange), changePct: num(j.priceChangePercent), ts: j.closeTime || Date.now(), source: 'binance' };
    }
  } catch (e) {}
  return null;
}
// staleMs:抓不到新報價時,可接受多舊的舊報價(只給畫面顯示用;交易不傳這個參數)
async function cryptoQuotes_(syms, ttl, staleMs, budgetMs, ctx) {
  ttl = ttl || CRYPTO_TTL_MS_;
  const out = {};
  const all = Promise.all(Array.from(new Set(syms)).map(async (c) => {
    const hit = cryptoMem_[c];
    if (hit && Date.now() - hit.at < ttl) { out[c] = hit.q; return; }
    if (!cryptoInflight_[c]) cryptoInflight_[c] = cryptoOne_(c).then((q) => { if (q) cryptoMem_[c] = { at: Date.now(), q }; return q; }).finally(() => { delete cryptoInflight_[c]; });
    let q = await cryptoInflight_[c];
    if (!q && staleMs && hit && Date.now() - hit.at < staleMs) q = hit.q;
    out[c] = q;
  }));
  if (budgetMs) {
    // 限時:budgetMs內沒回來的幣種先用舊報價(沒有就空),慢的繼續在背景跑,下次輪詢就有新的了
    if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(all.catch(() => {}));
    await Promise.race([all.catch(() => {}), new Promise((r) => setTimeout(r, budgetMs))]);
    const res = {};
    Array.from(new Set(syms)).forEach((c) => { const hit = cryptoMem_[c]; res[c] = out[c] !== undefined ? out[c] : (staleMs && hit && Date.now() - hit.at < staleMs ? hit.q : null); });
    return res;
  }
  await all;
  return out;
}
async function cryptoWithLock_(env, discordId, fn) {
  const accessToken = await getGoogleAccessToken(env);
  let lock = null, writeAttempted = false;
  try {
    await ensureCryptoSheets_(env, accessToken);
    lock = await acquireWorkerLock_(env, 'crypto', discordId, 8000, 25000);
    if (!lock) return { status: 'error', safeNoWrite: true, message: '系統忙碌，請稍後再試' };
    return await fn(accessToken, () => { writeAttempted = true; });
  } catch (e) {
    return { status: 'error', safeNoWrite: !writeAttempted, message: '加密貨幣交易發生錯誤：' + (e && e.message ? e.message : String(e)) };
  } finally { if (lock) await releaseWorkerLock_(env, 'crypto', discordId, lock); }
}
function cryptoPosOf_(rows, discordId) {
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    if ((r[0] || '').toString().replace("'", '') !== discordId.toString()) continue;
    out.push({ rowIdx: i + 1, symbol: (r[1] || '').toString(), name: (r[2] || '').toString(), qty: stockNum_(r[3], 0), cost: stockNum_(r[4], 0) });
  }
  return out;
}
function cryptoMarketStatus_(cfg) {
  if (!cfg.enabled) return { open: false, message: '加密貨幣交易目前沒有開放' };
  return stockWindowOpen_(cfg);
}


// ---------- 槓桿(合約式,做多/做空,保證金制,自動強平) ----------
function cryptoLevCfg_(rows) {
  const kv = {};
  for (let i = 1; i < (rows || []).length; i++) if (rows[i] && rows[i][0]) kv[rows[i][0].toString().trim()] = rows[i][1];
  const str = (k) => (kv[k] === undefined || kv[k] === null ? '' : kv[k].toString().replace(/'/g, '').trim());
  return {
    enabled: str('槓桿啟用').toUpperCase() === 'TRUE',
    maxLev: Math.max(1, Math.floor(stockNum_(kv['最大倍數'], 10))),
    liqRatio: Math.min(1, Math.max(0.5, stockNum_(kv['強平虧損比例'], 0.9))),
    minMargin: Math.max(0.01, stockNum_(kv['最低保證金'], 1)),
    maxPositions: Math.max(1, Math.floor(stockNum_(kv['單人最大持倉數'], 5))),
    liqDm: str('強平私訊通知').toUpperCase() !== 'FALSE',
    tradeDm: (() => { const v = str('開平倉私訊通知').toUpperCase(); return v === 'FALSE' || v === 'OFF' ? 'OFF' : (v === 'TEST' ? 'TEST' : 'ON'); })(),
  };
}
function levPosParse_(rows) {
  const out = [];
  for (let i = 1; i < (rows || []).length; i++) {
    const r = rows[i] || [];
    const id = (r[0] || '').toString();
    if (!id) continue;
    const p = { rowIdx: i + 1, id, discordId: (r[1] || '').toString().replace("'", ''), symbol: (r[2] || '').toString(), side: (r[3] || '').toString(), lev: stockNum_(r[4], 1), margin: stockNum_(r[5], 0), entry: stockNum_(r[6], 0), qty: stockNum_(r[7], 0), openFee: stockNum_(r[8], 0), openedAt: (r[9] || '').toString() };
    if (p.margin > 0 && p.qty > 0 && p.entry > 0) out.push(p);
  }
  return out;
}
function levEval_(p, price, cfg, lc) {
  const pnl = (p.side === '多' ? price - p.entry : p.entry - price) * p.qty * cfg.rate;
  const closeFee = p.qty * price * cfg.rate * cfg.feeRate;
  const liqPrice = p.side === '多' ? p.entry * (1 - lc.liqRatio / p.lev) : p.entry * (1 + lc.liqRatio / p.lev);
  return { pnl: stockRound2_(pnl), equity: stockRound2_(Math.max(0, p.margin + pnl)), closeFee, liqPrice, liq: pnl <= -p.margin * lc.liqRatio + 1e-9, payout: stockFloor2_(Math.max(0, p.margin + pnl - closeFee)) };
}
function levSendHook_(ctx, msg) { if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(queueWebhookWorker_(msg)); else queueWebhookWorker_(msg); }
// 開倉/平倉/強平機器人公告(貼到大獎頻道,不再私訊):OFF=不發、TEST=只公告管理員的交易(測試區)、ON=全部玩家
async function levNotifyTrade_(env, ctx, lc, discordId, title, body) {
  try {
    const m = lc && lc.tradeDm ? lc.tradeDm : 'ON';
    if (m === 'OFF') return;
    if (m === 'TEST' && !(await isAdminAllowed_(discordId, env))) return;
    const t = (m === 'TEST' ? '🧪【測試中】' : '') + title;
    levSendHook_(ctx, '[槓桿交易公告] ' + levSafe_(t) + '|' + discordId + '@' + levSafe_(body).replace(/\n/g, 'NEWLINEBREAKMARK'));
  } catch (e) {}
}
const levSafe_ = (x) => (x || '').toString().replace(/[|,:;=@%]/g, '、');
async function levCloseCore_(env, accessToken, mark, cfg, lc, pos, price, kind, ctx) {
  const playerRows = await fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player);
  const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
  let prow = -1;
  for (let i = 1; i < playerRows.length; i++) if (playerRows[i][0] && playerRows[i][0].toString().replace("'", '') === pos.discordId) { prow = i + 1; break; }
  if (ci === -1 || prow === -1) throw new Error('找不到玩家貨幣資料');
  const before = stockNum_(playerRows[prow - 1][ci], 0);
  const ev = levEval_(pos, price, cfg, lc);
  const payout = ev.payout;
  const pnl = stockRound2_(payout - pos.margin - pos.openFee);
  const disp = getDisplayCurrencyName(cfg.currency);
  const nowIso = new Date().toISOString();
  mark();
  await batchUpdateValues_(accessToken, env.SHEET_ID, [
    { range: `'${SHEET_NAMES.player}'!${colToA1_(ci)}${prow}`, values: [[stockRound2_(before + payout)]] },
    { range: `'${CRYPTO_LEV_SHEET_}'!A${pos.rowIdx}:J${pos.rowIdx}`, values: [['', '', '', '', '', '', '', '', '', '']] },
  ]);
  invalidateCraftCaches_(env, ['player']);
  const label = CRYPTO_NAMES_[pos.symbol] || pos.symbol;
  const act = kind === 'liq' ? '強平' : '平倉';
  const nm = label + '(' + pos.side + 'x' + pos.lev + ')';
  try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, CRYPTO_LOG_SHEET_, 'cryptoLog', [[nowIso, "'" + pos.discordId, pos.symbol, nm, act, pos.qty, price, payout, stockRound2_(ev.closeFee), pnl, stockRound2_(before + payout), cfg.currency]]); } catch (e) {}
  try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), pos.discordId, '[加密貨幣' + act + '] ' + nm, pos.qty, '', '', '以 ' + price + ' USD ' + act + ',返還 ' + payout + ' ' + disp + '(損益 ' + pnl + ')', '', '']); } catch (e) {}
  if (payout > 0) {
    levSendHook_(ctx, '[貨幣調整批次] ' + levSafe_('加密貨幣' + act + '：' + nm) + '|' + pos.discordId + '@+ ' + levSafe_(disp) + ' +' + payout + '|' + cfg.currency + ':' + pos.discordId + ':' + payout + '|SILENT');
  }
  {
    const ttl = kind === 'liq' ? '⚠️ 加密貨幣槓桿強平' : '✅ 加密貨幣槓桿平倉';
    await levNotifyTrade_(env, ctx, lc, pos.discordId, ttl, act + ' ' + nm + ' 成交價 ' + price + ' USD 損益 ' + pnl + ' ' + disp + (payout > 0 ? ' 返還 ' + payout : ' 保證金全賠未返還'));
  }
  return { payout, pnl, balance: stockRound2_(before + payout), kind, symbol: pos.symbol, side: pos.side, lev: pos.lev, price };
}
async function doCryptoLevOpen_(env, discordId, symRaw, sideRaw, levRaw, marginRaw, ctx) {
  const sym = (symRaw || '').toString().trim().toUpperCase();
  const side = sideRaw === 'short' || sideRaw === '空' ? '空' : (sideRaw === 'long' || sideRaw === '多' ? '多' : '');
  const lev = Math.floor(parseFloat(levRaw));
  const margin = stockFloor2_(parseFloat(marginRaw) || 0);
  if (!/^[A-Z0-9]{2,10}$/.test(sym)) return { status: 'error', safeNoWrite: true, message: '幣種代號格式不對' };
  if (!side) return { status: 'error', safeNoWrite: true, message: '請選擇做多或做空' };
  if (!(lev >= 1)) return { status: 'error', safeNoWrite: true, message: '倍數至少要1倍' };
  if (!(margin > 0)) return { status: 'error', safeNoWrite: true, message: '保證金要大於0' };
  return cryptoWithLock_(env, discordId, async (accessToken, mark) => {
    const [cfgRows, levRows, playerRows] = await Promise.all([cryptoFetch_(accessToken, env, CRYPTO_CFG_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LEV_SHEET_), fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player)]);
    const cfg = parseCryptoConfig_(cfgRows), lc = cryptoLevCfg_(cfgRows);
    if (!cfg.enabled || !cfg.currency) return { status: 'error', safeNoWrite: true, message: '加密貨幣交易目前沒有開放' };
    if (!lc.enabled) return { status: 'error', safeNoWrite: true, message: '槓桿交易目前沒有開放' };
    if (cfg.whitelist.indexOf(sym) === -1) return { status: 'error', safeNoWrite: true, message: '這個幣種目前不開放交易' };
    const market = cryptoMarketStatus_(cfg);
    if (!market.open) return { status: 'error', safeNoWrite: true, message: market.message || '目前不能交易' };
    if (lev > lc.maxLev) return { status: 'error', safeNoWrite: true, message: '最大只能開到 ' + lc.maxLev + ' 倍' };
    if (margin < lc.minMargin) return { status: 'error', safeNoWrite: true, message: '保證金最少要 ' + lc.minMargin };
    const mine = levPosParse_(levRows).filter((p) => p.discordId === discordId.toString());
    if (mine.length >= lc.maxPositions) return { status: 'error', safeNoWrite: true, message: '最多同時持有 ' + lc.maxPositions + ' 個槓桿倉位,請先平倉' };
    const q = (await cryptoQuotes_([sym], CRYPTO_TTL_MS_))[sym];
    if (!q) return { status: 'error', safeNoWrite: true, message: '抓不到「' + sym + '」的即時報價,請稍後再試' };
    const notional = margin * lev;
    if (cfg.maxShares > 0 && notional > cfg.maxShares * cfg.rate) return { status: 'error', safeNoWrite: true, message: '單筆倉位價值最多約 ' + cfg.maxShares + ' USD' };
    const qty = Math.floor(notional / (cfg.rate * q.price) * 1e8 + 1e-6) / 1e8;
    if (!(qty > 0)) return { status: 'error', safeNoWrite: true, message: '金額太小,請提高保證金' };
    const openFee = stockCeil2_(qty * q.price * cfg.rate * cfg.feeRate);
    const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
    let prow = -1;
    for (let i = 1; i < playerRows.length; i++) if (playerRows[i][0] && playerRows[i][0].toString().replace("'", '') === discordId.toString()) { prow = i + 1; break; }
    if (ci === -1 || prow === -1) return { status: 'error', safeNoWrite: true, message: '找不到你的貨幣資料(貨幣欄位:' + cfg.currency + '),請聯絡管理員' };
    const before = stockNum_(playerRows[prow - 1][ci], 0);
    const disp = getDisplayCurrencyName(cfg.currency);
    const total = stockRound2_(margin + openFee);
    if (before < total) return { status: 'error', safeNoWrite: true, message: disp + '不足:保證金 ' + margin + ' + 手續費 ' + openFee + ' = ' + total + ',你目前只有 ' + before };
    const posId = 'L' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    const nowIso = new Date().toISOString();
    mark();
    await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, CRYPTO_LEV_SHEET_, 'cryptoLev', [[posId, "'" + discordId, sym, side, lev, 0, q.price, 0, 0, nowIso]]);
    const fresh = levPosParseRaw_(await fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LEV_SHEET_), posId);
    if (!fresh) throw new Error('建立倉位資料失敗,請重試(尚未扣款)');
    await batchUpdateValues_(accessToken, env.SHEET_ID, [
      { range: `'${SHEET_NAMES.player}'!${colToA1_(ci)}${prow}`, values: [[stockRound2_(before - total)]] },
      { range: `'${CRYPTO_LEV_SHEET_}'!A${fresh}:J${fresh}`, values: [[posId, "'" + discordId, sym, side, lev, margin, q.price, qty, openFee, nowIso]] },
    ]);
    invalidateCraftCaches_(env, ['player']);
    const nm = (CRYPTO_NAMES_[sym] || sym) + '(' + side + 'x' + lev + ')';
    try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, CRYPTO_LOG_SHEET_, 'cryptoLog', [[nowIso, "'" + discordId, sym, nm, '開倉', qty, q.price, margin, openFee, '', stockRound2_(before - total), cfg.currency]]); } catch (e) {}
    try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), discordId.toString(), '[加密貨幣開倉] ' + nm, qty, '', '', '以 ' + q.price + ' USD 開倉,保證金 ' + margin + ' ' + disp + ',手續費 ' + openFee, '', '']); } catch (e) {}
    levSendHook_(ctx, '[貨幣調整批次] ' + levSafe_('加密貨幣開倉：' + nm) + '|' + discordId + '@- ' + levSafe_(disp) + ' -' + total + '|' + cfg.currency + ':' + discordId + ':' + (-total) + '|SILENT');
    const liqPrice = side === '多' ? q.price * (1 - lc.liqRatio / lev) : q.price * (1 + lc.liqRatio / lev);
    await levNotifyTrade_(env, ctx, lc, discordId, '📈 加密貨幣槓桿開倉', '開倉 ' + nm + ' 成交價 ' + q.price + ' USD 保證金 ' + margin + ' ' + disp + ' 強平價約 ' + (Math.round(liqPrice * 100) / 100) + ' USD');
    return { status: 'success', symbol: sym, side, lev, margin, price: q.price, qty, openFee, liqPrice, balance: stockRound2_(before - total), message: '✅ 開倉 ' + (CRYPTO_NAMES_[sym] || sym) + ' ' + side + ' ' + lev + ' 倍,開倉價 ' + q.price + ' USD,保證金 ' + margin + ' ' + disp + '(手續費 ' + openFee + '),強平價約 ' + (liqPrice >= 1000 ? Math.round(liqPrice) : Math.round(liqPrice * 10000) / 10000) + ' USD' };
  });
}
function levPosParseRaw_(rows, posId) { for (let i = 1; i < (rows || []).length; i++) if ((rows[i][0] || '').toString() === posId) return i + 1; return 0; }
async function doCryptoLevClose_(env, discordId, posId, ctx) {
  posId = (posId || '').toString();
  if (!posId) return { status: 'error', safeNoWrite: true, message: '缺少倉位ID' };
  return cryptoWithLock_(env, discordId, async (accessToken, mark) => {
    const [cfgRows, levRows] = await Promise.all([cryptoFetch_(accessToken, env, CRYPTO_CFG_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LEV_SHEET_)]);
    const cfg = parseCryptoConfig_(cfgRows), lc = cryptoLevCfg_(cfgRows);
    if (!cfg.currency) return { status: 'error', safeNoWrite: true, message: '加密貨幣設定尚未完成' };
    const pos = levPosParse_(levRows).find((p) => p.id === posId && p.discordId === discordId.toString());
    if (!pos) return { status: 'error', safeNoWrite: true, message: '找不到這個倉位(可能已經平倉或被強平)' };
    const q = (await cryptoQuotes_([pos.symbol], CRYPTO_TTL_MS_))[pos.symbol];
    if (!q) return { status: 'error', safeNoWrite: true, message: '抓不到即時報價,請稍後再試' };
    const ev = levEval_(pos, q.price, cfg, lc);
    const r = await levCloseCore_(env, accessToken, mark, cfg, lc, pos, q.price, ev.liq ? 'liq' : 'close', ctx);
    const disp = getDisplayCurrencyName(cfg.currency);
    return { status: 'success', ...r, message: (ev.liq ? '⚠️ 這個倉位已達強平條件,已強制平倉,' : '✅ 已平倉,') + '成交價 ' + q.price + ' USD,返還 ' + r.payout + ' ' + disp + '(損益 ' + (r.pnl >= 0 ? '+' : '') + r.pnl + ')' };
  });
}
// 每分鐘由排程呼叫:達強平條件的倉位自動強制平倉(不論有沒有人在線)
async function runCryptoLiquidationScan_(env, ctx) {
  const accessToken = await getGoogleAccessToken(env);
  const cfgRows = await getCachedSheetData_('cryptoCfg:' + env.SHEET_ID, () => cryptoFetch_(accessToken, env, CRYPTO_CFG_SHEET_), 30000);
  if (!cfgRows || cfgRows.length === 0) return;
  const cfg = parseCryptoConfig_(cfgRows), lc = cryptoLevCfg_(cfgRows);
  if (!cfg.currency) return;
  const positions = levPosParse_(await fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LEV_SHEET_));
  if (!positions.length) return;
  const quotes = await cryptoQuotes_(positions.map((p) => p.symbol), 5000);
  const hit = positions.filter((p) => { const q = quotes[p.symbol]; return q && levEval_(p, q.price, cfg, lc).liq; }).slice(0, 10);
  for (const p of hit) {
    try {
      await cryptoWithLock_(env, p.discordId, async (at, mark) => {
        const fresh = levPosParse_(await fetchOptionalSheet_(at, env.SHEET_ID, CRYPTO_LEV_SHEET_)).find((x) => x.id === p.id);
        if (!fresh) return { status: 'success' };
        const q = (await cryptoQuotes_([fresh.symbol], 3000))[fresh.symbol];
        if (!q || !levEval_(fresh, q.price, cfg, lc).liq) return { status: 'success' };
        await levCloseCore_(env, at, mark, cfg, lc, fresh, q.price, 'liq', ctx);
        return { status: 'success' };
      });
    } catch (e) { console.error('強平失敗:', e && e.message ? e.message : e); }
  }
}

// ---------- 走勢圖(60秒共用快取) ----------
const chartMem_ = {};
async function doCryptoChart_(symRaw, range) {
  const sym = (symRaw || '').toString().trim().toUpperCase();
  if (!/^[A-Z0-9]{2,10}$/.test(sym)) return { status: 'error', message: '幣種代號格式不對' };
  const spec = { '1h': [60, 60], '1d': [900, 96], '7d': [3600, 168], '30d': [21600, 120] }[range] || [900, 96];
  const key = 'c:' + sym + ':' + spec[0];
  const hit = chartMem_[key];
  if (hit && Date.now() - hit.at < 60000) return hit.v;
  const res = await cryptoCbGet_('https://api.exchange.coinbase.com/products/' + sym + '-USD/candles?granularity=' + spec[0]);
  if (!res || !res.ok) { if (hit) return hit.v; return { status: 'error', message: '走勢資料暫時抓不到,請稍後再試' }; }
  const arr = await res.json();
  const pts = (Array.isArray(arr) ? arr : []).slice(0, spec[1]).reverse().map((r) => ({ t: r[0] * 1000, o: r[3], h: r[2], l: r[1], c: r[4], v: r[5] })).filter((x) => x.c > 0);
  const v = { status: 'success', symbol: sym, range, points: pts };
  chartMem_[key] = { at: Date.now(), v };
  return v;
}
async function doStockChart_(codeRaw, range, env) {
  const code = (codeRaw || '').toString().trim().toUpperCase();
  if (!/^[0-9A-Z]{4,6}$/.test(code)) return { status: 'error', message: '股票代號格式不對' };
  const spec = { '1d': ['1d', '5m'], '5d': ['5d', '15m'], '1m': ['1mo', '1d'], '6m': ['6mo', '1d'] }[range] || ['1d', '5m'];
  const key = 's:' + code + ':' + spec.join('');
  const hit = chartMem_[key];
  if (hit && Date.now() - hit.at < 60000) return hit.v;
  // 🌟 當日走勢優先用富果即時 K 線(5分K,幾乎即時);失敗/沒密鑰/額度用完才退回 Yahoo(延遲約20分鐘)
  if (range === '1d' || !range) {
    try {
      twSetEnv_(env);
      if (twFugleKey_ && Date.now() >= twFugleDownUntil_ && twFugleBudgetTake_()) {
        const res = await fetchWithTimeout_('https://api.fugle.tw/marketdata/v1.0/stock/intraday/candles/' + encodeURIComponent(code) + '?timeframe=5', { headers: { 'X-API-KEY': twFugleKey_, 'Accept': 'application/json' } }, 6000);
        if (res.status === 429) twFugleDownUntil_ = Date.now() + 20000;
        else if (res.ok) {
          const j = await res.json();
          const arr = Array.isArray(j && j.data) ? j.data : [];
          const pts = arr.map((r) => ({ t: Date.parse(r.date), o: r.open, h: r.high, l: r.low, c: r.close, v: r.volume || 0 })).filter((x) => x.t > 0 && x.c > 0).sort((a, b) => a.t - b.t);
          if (pts.length >= 2) {
            let prevClose = null;
            try { const q = (await fetchTwQuotes_([code], { ttl: 60000, relayOk: true }))[code]; prevClose = q && q.prevClose || null; } catch (e) {}
            const v = { status: 'success', code, range: '1d', points: pts, prevClose, delayed: false, source: 'fugle' };
            chartMem_[key] = { at: Date.now(), v };
            return v;
          }
        }
      }
    } catch (e) {}
  }
  for (const suf of ['.TW', '.TWO']) {
    try {
      const res = await fetchWithTimeout_('https://query1.finance.yahoo.com/v8/finance/chart/' + code + suf + '?range=' + spec[0] + '&interval=' + spec[1], { headers: { 'User-Agent': TW_UA_, 'Accept': 'application/json' } }, 6000);
      if (!res.ok) continue;
      const j = await res.json();
      const r = j && j.chart && j.chart.result && j.chart.result[0];
      if (!r || !r.timestamp) continue;
      const cl = (r.indicators && r.indicators.quote && r.indicators.quote[0] && r.indicators.quote[0].close) || [];
      const qd = (r.indicators && r.indicators.quote && r.indicators.quote[0]) || {};
      const pts = [];
      r.timestamp.forEach((t, i) => { if (cl[i] > 0) pts.push({ t: t * 1000, o: qd.open && qd.open[i] > 0 ? qd.open[i] : cl[i], h: qd.high && qd.high[i] > 0 ? qd.high[i] : cl[i], l: qd.low && qd.low[i] > 0 ? qd.low[i] : cl[i], c: cl[i], v: qd.volume ? qd.volume[i] || 0 : 0 }); });
      if (pts.length < 2) continue;
      const v = { status: 'success', code, range, points: pts, prevClose: (r.meta && (r.meta.chartPreviousClose || r.meta.previousClose)) || null, delayed: true };
      chartMem_[key] = { at: Date.now(), v };
      return v;
    } catch (e) {}
  }
  if (hit) return hit.v;
  return { status: 'error', message: '走勢資料暫時抓不到,請稍後再試' };
}
async function doCryptoStatus_(env) {
  const accessToken = await getGoogleAccessToken(env);
  let cRows_ = null;
  if (fastExtra_(env)) { try { const r_ = (await snapApi_(env).get('cryptocfg', 5000, 60000)).rows; if (r_ && r_.length) cRows_ = r_; } catch (e) {} }
  const cfg = parseCryptoConfig_(cRows_ || await getCachedSheetData_('cryptoCfg:' + env.SHEET_ID, () => cryptoFetch_(accessToken, env, CRYPTO_CFG_SHEET_), 30000));
  const today = twDateStr_(twNow_());
  const inRange = entryInRange_(cfg);
  return { status: 'success', enabled: cfg.enabled && !!cfg.currency && inRange };
}
async function doCryptoState_(env, discordId, ctx) {
  const accessToken = await getGoogleAccessToken(env);
  await ensureCryptoSheets_(env, accessToken);
  const [cfgRows, posRows, logRows, playerRows, levRows] = await Promise.all([
    cryptoFetch_(accessToken, env, CRYPTO_CFG_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_POS_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LOG_SHEET_), fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LEV_SHEET_),
  ]);
  const cfg = parseCryptoConfig_(cfgRows);
  if (!cfg.enabled || !cfg.currency) return { status: 'success', enabled: false, message: '加密貨幣交易目前沒有開放' };
  const market = cryptoMarketStatus_(cfg);
  const mine = cryptoPosOf_(posRows, discordId).filter((p) => p.qty > 0);
  const levAll = levPosParse_(levRows).filter((p) => p.discordId === discordId.toString());
  const quotes = await cryptoQuotes_(cfg.whitelist.concat(mine.map((p) => p.symbol)).concat(levAll.map((p) => p.symbol)), 15000, 180000, 2500, ctx);
  const board = cfg.whitelist.map((sym) => { const q = quotes[sym]; return q ? { symbol: sym, name: q.name, price: q.price, priceCur: stockRound2_(q.price * cfg.rate), changePct: q.changePct === null ? null : stockRound2_(q.changePct) } : { symbol: sym, name: CRYPTO_NAMES_[sym] || sym, price: null, priceCur: null, changePct: null }; });
  let totalValue = 0, totalCost = 0;
  const holdings = mine.map((p) => {
    const q = quotes[p.symbol]; const value = q ? stockFloor2_(q.price * cfg.rate * p.qty) : null;
    if (value !== null) totalValue += value; totalCost += p.cost;
    return { symbol: p.symbol, name: p.name || (q && q.name) || p.symbol, qty: p.qty, cost: stockRound2_(p.cost), price: q ? q.price : null, value, pnl: value !== null ? stockRound2_(value - p.cost) : null, pnlPct: value !== null && p.cost > 0 ? stockRound2_((value - p.cost) / p.cost * 100) : null };
  });
  const lc = cryptoLevCfg_(cfgRows);
  const lq = quotes;
  let levEquity = 0, levCost = 0;
  const levPositions = levAll.map((p) => {
    const q = lq[p.symbol]; levCost += p.margin + p.openFee;
    if (!q) return { id: p.id, symbol: p.symbol, side: p.side, lev: p.lev, margin: p.margin, entry: p.entry, qty: p.qty, price: null, pnl: null, equity: null, liqPrice: null, pnlPct: null };
    const ev = levEval_(p, q.price, cfg, lc); levEquity += ev.equity;
    return { id: p.id, symbol: p.symbol, side: p.side, lev: p.lev, margin: p.margin, entry: p.entry, qty: p.qty, price: q.price, pnl: ev.pnl, equity: ev.equity, liqPrice: ev.liqPrice, pnlPct: stockRound2_(ev.pnl / p.margin * 100) };
  });
  totalValue += levEquity; totalCost += levCost;
  const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
  let balance = null;
  for (let i = 1; i < playerRows.length; i++) if (playerRows[i][0] && playerRows[i][0].toString().replace("'", '') === discordId.toString()) { balance = ci === -1 ? null : stockNum_(playerRows[i][ci], 0); break; }
  const history = [];
  for (let i = logRows.length - 1; i >= 1 && history.length < 20; i--) {
    const r = logRows[i];
    if ((r[1] || '').toString().replace("'", '') !== discordId.toString()) continue;
    history.push({ time: (r[0] || '').toString(), symbol: (r[2] || '').toString(), name: (r[3] || '').toString(), action: (r[4] || '').toString(), qty: stockNum_(r[5], 0), price: stockNum_(r[6], 0), amount: stockNum_(r[7], 0), pnl: r[9] === '' || r[9] === undefined ? null : stockNum_(r[9], 0) });
  }
  return { status: 'success', enabled: true, open: market.open, openMessage: market.message, ...closeInfo_(cfg), currency: cfg.currency, currencyDisplay: getDisplayCurrencyName(cfg.currency), rate: cfg.rate, feeRate: cfg.feeRate, maxAmount: cfg.maxShares, lev: { enabled: lc.enabled, maxLev: lc.maxLev, liqRatio: lc.liqRatio, minMargin: lc.minMargin, maxPositions: lc.maxPositions, positions: levPositions }, board, balance, holdings, totalValue: stockRound2_(totalValue), totalCost: stockRound2_(totalCost), totalPnl: stockRound2_(totalValue - totalCost), history };
}
async function doCryptoTrade_(env, discordId, side, symRaw, qtyRaw, ctx, amountRaw) {
  const sym = (symRaw || '').toString().trim().toUpperCase();
  // 🌟🆕 依金額買進:amount=要花多少遊戲貨幣,數量在成交當下依即時報價自動換算(含手續費、不超過這個金額)
  const byAmount = side === 'buy' && parseFloat(amountRaw) > 0;
  const amountBudget = byAmount ? parseFloat(amountRaw) : 0;
  let qty = byAmount ? 1 : cryptoQty_(qtyRaw);
  if (!/^[A-Z0-9]{2,10}$/.test(sym)) return { status: 'error', safeNoWrite: true, message: '幣種代號格式不對' };
  if (!(qty > 0)) return { status: 'error', safeNoWrite: true, message: '數量要大於0(最多到小數第8位)' };
  return cryptoWithLock_(env, discordId, async (accessToken, mark) => {
    const [cfgRows, posRows0, playerRows] = await Promise.all([cryptoFetch_(accessToken, env, CRYPTO_CFG_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_POS_SHEET_), fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player)]);
    const cfg = parseCryptoConfig_(cfgRows);
    if (!cfg.enabled || !cfg.currency) return { status: 'error', safeNoWrite: true, message: '加密貨幣交易目前沒有開放' };
    if (cfg.whitelist.indexOf(sym) === -1) return { status: 'error', safeNoWrite: true, message: '這個幣種目前不開放交易' };
    const market = cryptoMarketStatus_(cfg);
    if (!market.open) return { status: 'error', safeNoWrite: true, message: market.message || '目前不能交易' };
    const q = (await cryptoQuotes_([sym], CRYPTO_TTL_MS_))[sym];
    if (!q) return { status: 'error', safeNoWrite: true, message: '抓不到「' + sym + '」的即時報價,請稍後再試' };
    if (byAmount) {
      qty = cryptoQty_(amountBudget / (q.price * cfg.rate * (1 + cfg.feeRate)));
      const costOf = (n) => { const g = n * q.price * cfg.rate; return stockCeil2_(g + stockCeil2_(g * cfg.feeRate)); };
      while (qty > 0 && costOf(qty) > amountBudget) qty = Math.max(0, Math.round((qty - 1e-8) * 1e8) / 1e8);
      if (!(qty > 0)) return { status: 'error', safeNoWrite: true, message: '金額太小,買不到任何 ' + sym };
    }
    const gross = qty * q.price * cfg.rate;
    if (cfg.maxShares > 0 && gross > cfg.maxShares * cfg.rate) return { status: 'error', safeNoWrite: true, message: '單筆最多只能交易約 ' + cfg.maxShares + ' USD' };
    const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
    let prow = -1;
    for (let p = 1; p < playerRows.length; p++) if (playerRows[p][0] && playerRows[p][0].toString().replace("'", '') === discordId.toString()) { prow = p + 1; break; }
    if (ci === -1 || prow === -1) return { status: 'error', safeNoWrite: true, message: '找不到你的貨幣資料(貨幣欄位:' + cfg.currency + '),請聯絡管理員' };
    const before = stockNum_(playerRows[prow - 1][ci], 0);
    const disp = getDisplayCurrencyName(cfg.currency);
    let pos = cryptoPosOf_(posRows0, discordId).find((p) => p.symbol === sym);
    const nowIso = new Date().toISOString();
    const playerCell = `'${SHEET_NAMES.player}'!${colToA1_(ci)}${prow}`;
    const sendHook = (x) => { if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(queueWebhookWorker_(x)); else queueWebhookWorker_(x); };
    const safe_ = (x) => (x || '').toString().replace(/[|,:;=@%]/g, '、');
    const reason = '加密貨幣' + (side === 'buy' ? '買進' : '賣出') + '：' + sym;
    const name = q.name;
    if (side === 'buy') {
      const fee = stockCeil2_(gross * cfg.feeRate);
      const cost = stockCeil2_(gross + fee);
      if (!(cost > 0)) return { status: 'error', safeNoWrite: true, message: '金額太小,請提高數量' };
      if (before < cost) return { status: 'error', safeNoWrite: true, message: disp + '不足:買進 ' + qty + ' ' + sym + ' 需要約 ' + cost + ',你目前只有 ' + before };
      mark();
      if (!pos) {
        await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, CRYPTO_POS_SHEET_, 'cryptoPos', [["'" + discordId, sym, name, 0, 0, nowIso]]);
        const fresh = await fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_POS_SHEET_);
        pos = cryptoPosOf_(fresh, discordId).filter((p) => p.symbol === sym).pop();
        if (!pos) throw new Error('建立持倉資料失敗,請重試(尚未扣款)');
      }
      const newQty = Math.round((pos.qty + qty) * 1e8) / 1e8, newCost = stockRound2_(pos.cost + cost);
      await batchUpdateValues_(accessToken, env.SHEET_ID, [{ range: playerCell, values: [[stockRound2_(before - cost)]] }, { range: `'${CRYPTO_POS_SHEET_}'!C${pos.rowIdx}:F${pos.rowIdx}`, values: [[name, newQty, newCost, nowIso]] }]);
      invalidateCraftCaches_(env, ['player']);
      try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, CRYPTO_LOG_SHEET_, 'cryptoLog', [[nowIso, "'" + discordId, sym, name, '買進', qty, q.price, cost, fee, '', stockRound2_(before - cost), cfg.currency]]); } catch (e) {}
      try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), discordId.toString(), '[加密貨幣買進] ' + name + '(' + sym + ')', qty, '', '', '以 ' + q.price + ' USD 買進 ' + qty + ' ' + sym + ',花費 ' + cost + ' ' + disp, '', '']); } catch (e) {}
      sendHook('[貨幣調整批次] ' + safe_(reason) + '|' + discordId + '@- ' + safe_(disp) + ' -' + cost + '|' + cfg.currency + ':' + discordId + ':' + (-cost) + '|SILENT');
      return { status: 'success', side, symbol: sym, qty, price: q.price, amount: cost, balance: stockRound2_(before - cost), message: '✅ 買進 ' + name + ' ' + qty + ' ' + sym + ',成交價 ' + q.price + ' USD,花費 ' + cost + ' ' + disp };
    }
    if (!pos || pos.qty + 1e-9 < qty) return { status: 'error', safeNoWrite: true, message: '你只持有 ' + (pos ? pos.qty : 0) + ' ' + sym + ',不夠賣 ' + qty };
    const fee = stockCeil2_(gross * cfg.feeRate);
    const proceeds = stockFloor2_(gross - fee);
    if (!(proceeds > 0)) return { status: 'error', safeNoWrite: true, message: '金額太小,請提高數量' };
    const sellAll = Math.abs(pos.qty - qty) < 1e-9;
    const costBasis = sellAll ? pos.cost : stockRound2_(pos.cost * qty / pos.qty);
    const pnl = stockRound2_(proceeds - costBasis);
    const newQty = sellAll ? 0 : Math.round((pos.qty - qty) * 1e8) / 1e8, newCost = sellAll ? 0 : stockRound2_(pos.cost - costBasis);
    mark();
    await batchUpdateValues_(accessToken, env.SHEET_ID, [{ range: playerCell, values: [[stockRound2_(before + proceeds)]] }, { range: `'${CRYPTO_POS_SHEET_}'!D${pos.rowIdx}:F${pos.rowIdx}`, values: [[newQty, newCost, nowIso]] }]);
    invalidateCraftCaches_(env, ['player']);
    try { await appendRowsWithLockedRange_(env, accessToken, env.SHEET_ID, CRYPTO_LOG_SHEET_, 'cryptoLog', [[nowIso, "'" + discordId, sym, name, '賣出', qty, q.price, proceeds, fee, pnl, stockRound2_(before + proceeds), cfg.currency]]); } catch (e) {}
    try { await appendHistoryRowSafe_(env, accessToken, env.SHEET_ID, [new Date(), discordId.toString(), '[加密貨幣賣出] ' + name + '(' + sym + ')', qty, '', '', '以 ' + q.price + ' USD 賣出 ' + qty + ' ' + sym + ',獲得 ' + proceeds + ' ' + disp + '(損益 ' + pnl + ')', '', '']); } catch (e) {}
    sendHook('[貨幣調整批次] ' + safe_(reason) + '|' + discordId + '@+ ' + safe_(disp) + ' +' + proceeds + '|' + cfg.currency + ':' + discordId + ':' + proceeds + '|SILENT');
    return { status: 'success', side, symbol: sym, qty, price: q.price, amount: proceeds, pnl, balance: stockRound2_(before + proceeds), message: '✅ 賣出 ' + name + ' ' + qty + ' ' + sym + ',成交價 ' + q.price + ' USD,獲得 ' + proceeds + ' ' + disp + '(損益 ' + (pnl >= 0 ? '+' : '') + pnl + ')' };
  });
}
let cryptoLbMemo_ = { at: 0, data: null };
// 加密貨幣排行榜(與台股分開):總損益、總資產。90秒共用快取。
let cryptoLbInflight_ = null;
async function cryptoLbRefresh_(env) {
  if (!cryptoLbInflight_) cryptoLbInflight_ = (async () => {
    const accessToken = await getGoogleAccessToken(env);
    await ensureCryptoSheets_(env, accessToken);
    const [cfgRows, posRows, logRows, playerRows] = await Promise.all([
      cryptoFetch_(accessToken, env, CRYPTO_CFG_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_POS_SHEET_), fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LOG_SHEET_), fetchSingleSheet(accessToken, env.SHEET_ID, SHEET_NAMES.player),
    ]);
    const cfg = parseCryptoConfig_(cfgRows);
    if (!cfg.enabled || !cfg.currency) { cryptoLbMemo_ = { at: Date.now(), data: null, off: true }; return; }
    const idOf = (v) => (v || '').toString().replace("'", '');
    const players = {};
    const get = (id) => (players[id] = players[id] || { id, realized: 0, cost: 0, value: 0, holdCount: 0, trades: 0 });
    for (let i = 1; i < logRows.length; i++) { const r = logRows[i]; const id = idOf(r[1]); if (!id) continue; if (((r[11] || '').toString().trim() || cfg.currency) !== cfg.currency) continue; const pl = get(id); pl.trades++; if (['賣出', '平倉', '強平'].indexOf((r[4] || '').toString()) !== -1) pl.realized += stockNum_(r[9], 0); }
    const lcL = cryptoLevCfg_(cfgRows);
    const levAllL = levPosParse_(await fetchOptionalSheet_(accessToken, env.SHEET_ID, CRYPTO_LEV_SHEET_));
    const holds = [];
    for (let i = 1; i < posRows.length; i++) { const r = posRows[i]; const id = idOf(r[0]); const qty = stockNum_(r[3], 0); if (!id || qty <= 0) continue; holds.push({ id, sym: (r[1] || '').toString(), qty, cost: stockNum_(r[4], 0) }); get(id); }
    let quotes = {}; try { quotes = await cryptoQuotes_(holds.map((h) => h.sym).concat(levAllL.map((p) => p.symbol)), 20000, 300000, 4000); } catch (e) {}
    holds.forEach((h) => { const pl = get(h.id); const q = quotes[h.sym]; pl.cost += h.cost; pl.holdCount++; pl.value += q ? stockFloor2_(q.price * cfg.rate * h.qty) : h.cost; });
    levAllL.forEach((p) => { const pl = get(p.discordId); const q = quotes[p.symbol]; pl.cost += p.margin + p.openFee; pl.holdCount++; pl.value += q ? levEval_(p, q.price, cfg, lcL).equity : p.margin; });
    const hdr = playerRows[0] || []; const ci = hdr.indexOf(cfg.currency);
    const info = {};
    for (let i = 1; i < playerRows.length; i++) { const id = idOf(playerRows[i][0]); if (id && players[id]) info[id] = { name: (playerRows[i][1] || '').toString(), bal: ci === -1 ? 0 : stockNum_(playerRows[i][ci], 0) }; }
    const list = Object.values(players).map((pl) => { const inf = info[pl.id] || { name: '(未知)', bal: 0 }; return { id: pl.id, name: inf.name, pnl: stockRound2_(pl.realized + (pl.value - pl.cost)), realized: stockRound2_(pl.realized), unreal: stockRound2_(pl.value - pl.cost), assets: stockRound2_(inf.bal + pl.value), holdCount: pl.holdCount, trades: pl.trades }; });
    cryptoLbMemo_ = { at: Date.now(), data: { list, currencyDisplay: getDisplayCurrencyName(cfg.currency) } };
  })().finally(() => { cryptoLbInflight_ = null; });
  return cryptoLbInflight_;
}
async function doCryptoLeaderboard_(env, discordId, ctx) {
  // 先回舊資料(10分鐘內),過期就背景重算;完全沒資料才等
  const age = Date.now() - cryptoLbMemo_.at;
  if (cryptoLbMemo_.at && age > 20000 && age < 600000 && ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(cryptoLbRefresh_(env).catch(() => {}));
  else if (!cryptoLbMemo_.at || age >= 600000 || (age > 20000 && !(ctx && typeof ctx.waitUntil === 'function'))) await cryptoLbRefresh_(env);
  if (cryptoLbMemo_.off || !cryptoLbMemo_.data) return { status: 'success', enabled: false };
  const d = cryptoLbMemo_.data;
  const me = discordId.toString();
  const rank = (key) => {
    const sorted = d.list.slice().sort((a, b) => b[key] - a[key]);
    const my = sorted.findIndex((x) => x.id === me);
    return { top: sorted.slice(0, 20).map((x, i) => ({ rank: i + 1, name: x.name, value: x[key], me: x.id === me })), me: my === -1 ? null : { rank: my + 1, value: sorted[my][key] }, total: sorted.length };
  };
  return { status: 'success', enabled: true, currencyDisplay: d.currencyDisplay, updatedAt: cryptoLbMemo_.at, pnl: rank('pnl'), assets: rank('assets'), realized: rank('realized'), unreal: rank('unreal') };
}
