        const tstr = lu ? String(lu.getUTCHours()).padStart(2, '0') + ':' + String(lu.getUTCMinutes()).padStart(2, '0') + ':' + String(lu.getUTCSeconds()).padStart(2, '0') : '';
        out.steps.push({ step: '全市場快照 ' + mkt, ok: arr.length > 0, detail: '一次取得 ' + arr.length + ' 檔(資料日期 ' + (j.date || '?') + ' ' + (j.time || '') + ')' + (f ? ';' + code + ' ' + (f.name || '') + ' 價格 ' + (f.lastPrice != null ? f.lastPrice : f.closePrice) + ',更新 ' + tstr : ';此市場沒有 ' + code), ms: Date.now() - ts0 });
