function buildHistoryPage(discordId, pageRaw, pageSizeRaw, historyData, kindRaw) {
  const kindFilter = kindRaw === 'buy' || kindRaw === 'grant' ? kindRaw : 'all'; // all=全部 buy=只看購買 grant=只看團任/團戰等發放
  let page = parseInt(pageRaw) || 1;
  let pageSize = parseInt(pageSizeRaw) || 10;
  if (page < 1) page = 1;
  if (pageSize < 1) pageSize = 10;
  if (pageSize > 50) pageSize = 50;

  const idStr = discordId.toString();
  const matched = [];
  const needed = page * pageSize + 1;

  for (let i = historyData.length - 1; i >= 1 && matched.length < needed; i--) {
    const row = historyData[i];
    if (!row[0] || !row[1]) continue;
    if (row[1].toString().replace("'", '') === idStr) {
      const tDate = sheetsSerialToDate(row[0]);
      const noteTextForBuyCheck = row[2] ? row[2].toString() : '';
      if (/^\[[A-Za-z]+\]$/.test(noteTextForBuyCheck)) continue;
      const isGrantRow_ = /^\[[^\]]*發放\]\s/.test(noteTextForBuyCheck);
      if (kindFilter === 'buy' && isGrantRow_) continue;
      if (kindFilter === 'grant' && !isGrantRow_) continue;
      const cleanItemNameForHistory = row[2] ? getRevealedItemName_(row[2].toString().replace(/\[OPT\d+\]$/, '')) : row[2];
      matched.push({
        time: tDate ? formatDateTimeStr(tDate) : '時間讀取錯誤',
        itemName: cleanItemNameForHistory,
        qty: row[3],
        keys: row[5] || '無',
        drawn: row[6] || '',
        beforeBal: row[7] !== '' && row[7] !== undefined ? row[7] : null,
        afterBal: row[8] !== '' && row[8] !== undefined ? row[8] : null,
        altCost: row[9] || '',
        extraCost: row[10] || '',
        totalRewards: row[11] || '',
      });
    }
  }

  const hasMore = matched.length > page * pageSize;
  const startIdx = (page - 1) * pageSize;
  const pageItems = matched.slice(startIdx, startIdx + pageSize);

  return { status: 'success', history: pageItems, page, pageSize, hasMore };
}

function buildAuctions(discordId, auctionData, bidData, playerData, roleMapData, categoryOrderData) {
  const userRoles = getUserRolesFromData(discordId, playerData);
  const roleMap = getGuildRoleMapFromData(roleMapData);
  const now = Date.now();
  const auctions = [];

  const playerHeadersForAlt = playerData[0] || [];
  let playerRowForAlt = -1;
  for (let pa = 1; pa < playerData.length; pa++) {
    if (playerData[pa][0] && playerData[pa][0].toString().replace("'", '') === discordId.toString()) { playerRowForAlt = pa; break; }
  }
  function getAuctionAltBalance(altCurrencyName) {
    if (!altCurrencyName || playerRowForAlt === -1) return 0;
    const colIdx = playerHeadersForAlt.indexOf(altCurrencyName);
    if (colIdx === -1) return 0;
    return parseInt(playerData[playerRowForAlt][colIdx]) || 0;
  }

  const categoryOrder = [];
  if (categoryOrderData && categoryOrderData.length > 1) {
    for (let c = 1; c < categoryOrderData.length; c++) {
      if (categoryOrderData[c][1]) categoryOrder.push(categoryOrderData[c][1].toString().trim());
    }
  }

  for (let i = 1; i < auctionData.length; i++) {
    const row = auctionData[i];
    const name = row[0];
    if (!name) continue;

    const draftStatus = row[19] ? row[19].toString().trim().toUpperCase() : '';
    if (draftStatus === 'DRAFT') continue;
    const sortOrder = row[20] !== '' && row[20] !== undefined ? parseInt(row[20]) : null;

    let auctionId = row[10] ? row[10].toString().trim() : '';
    if (!auctionId) auctionId = 'TEMP' + i;

    const startBid = parseInt(row[1]) || 0;
    let type = (row[2] || 'PUBLIC').toString().trim().toUpperCase();
    if (type !== 'SEALED' && type !== 'SEALED_LOW') type = 'PUBLIC';
    const endDate = dateSerialToTime(row[3]);
    const extendTriggerMin = row[4] !== '' && row[4] !== undefined ? parseInt(row[4]) : null;
    const extendByMin = row[5] !== '' && row[5] !== undefined ? parseInt(row[5]) : null;
    const manualStatus = row[6] ? row[6].toString().trim().toUpperCase() : '';
    const currencyName = row[7] ? row[7].toString().trim() : '升階2';
    const displayCurrency = currencyName === '升階2' ? '幻彩水晶' : currencyName;
    const imageUrl = row[8] ? row[8].toString().trim() : '';
    const remark = row[9] ? row[9].toString().trim() : '';
    const currentHighBid = row[11] !== '' && row[11] !== undefined ? parseInt(row[11]) : startBid;
    const currentHighBidder = row[12] ? row[12].toString().trim() : '';
    const settled = row[13] === true || row[13] === 'TRUE';
    const requiredRoleStr = row[14] ? row[14].toString().trim() : '';
    const startDate = dateSerialToTime(row[15]);
    const category = row[16] ? row[16].toString().trim() : '未分類';

    let altCurrency = row[17] ? row[17].toString().trim() : '';
    const altCurrencyRate = row[18] !== '' && row[18] !== undefined ? parseFloat(row[18]) : 0;
    if (!(altCurrencyRate > 0)) altCurrency = '';
    const altCurrencyBalance = altCurrency ? getAuctionAltBalance(altCurrency) : 0;
    const altCurrencyDisplay = getDisplayCurrencyName(altCurrency);

    const isNotStarted = !!(startDate && now < startDate);
    const isEnded = !isNotStarted && (manualStatus === 'CLOSED' || (endDate && now > endDate));

    let requiredRoleNames = [];
    let roleRequirementMode = 'ANY', roleRequirementMinCount = 1;
    if (requiredRoleStr) {
      const roleReq = parseRoleRequirement(requiredRoleStr);
      roleRequirementMode = roleReq.mode;
      roleRequirementMinCount = roleReq.minCount;
      requiredRoleNames = roleReq.ids.map((id) => roleMap[id] || '未知身分組' + id);
    }
    const hasRolePermission = checkRolePermission(userRoles, requiredRoleStr);

    let myActiveBid = null;
    let myActiveBidAlt = 0;
    for (let b = bidData.length - 1; b >= 1; b--) {
      if (
        bidData[b][1] && bidData[b][1].toString() === auctionId &&
        bidData[b][2] && bidData[b][2].toString().replace("'", '') === discordId.toString() &&
        bidData[b][4] === 'FROZEN'
      ) {
        myActiveBid = parseInt(bidData[b][3]) || 0;
        myActiveBidAlt = bidData[b][5] !== '' && bidData[b][5] !== undefined ? (parseInt(bidData[b][5]) || 0) : 0;
        break;
      }
    }

    let state;
    if (isNotStarted) state = 'not_started';
    else if (isEnded) state = settled ? 'ended' : 'pending_settlement';
    else if (!hasRolePermission) state = 'no_permission';
    else state = 'open';

    let currentHighBidderName = null;
    if (type === 'PUBLIC' && currentHighBidder !== '' && currentHighBidder !== discordId.toString()) {
      currentHighBidderName = getPlayerDisplayNameFromData(currentHighBidder, playerData) || ('玩家' + currentHighBidder.slice(-4));
    }

    let myWonThisAuction = false;
    for (let bw = 1; bw < bidData.length; bw++) {
      if (bidData[bw][1] && bidData[bw][1].toString() === auctionId &&
          bidData[bw][2] && bidData[bw][2].toString().replace("'", '') === discordId.toString() &&
          bidData[bw][4] === 'WON') { myWonThisAuction = true; break; }
    }

    let winnerCount = row[21] !== '' && row[21] !== undefined ? parseInt(row[21]) : 1;
    if (!(winnerCount >= 1)) winnerCount = 1;
    const raffleSlots = row[22] !== '' && row[22] !== undefined ? parseInt(row[22]) : 0;
    const raffleResultRaw = row[24] ? row[24].toString().trim() : '';
    const raffleWinnersList = raffleResultRaw ? safeParseJSON(raffleResultRaw) : null;
    let myRafflePrize = null;
    if (raffleWinnersList) {
      for (let rw = 0; rw < raffleWinnersList.length; rw++) {
        if (raffleWinnersList[rw].discordId === discordId.toString()) { myRafflePrize = raffleWinnersList[rw].prize; break; }
      }
    }

    auctions.push({
      id: auctionId, name, type, startBid,
      startDate, endDate, currencyName, displayCurrency,
      imageUrl, remark, state,
      currentHighBid: type === 'PUBLIC' ? currentHighBid : null,
      currentHighBidderName,
      hasAnyBid: currentHighBidder !== '',
      currentHighBidderIsMe: currentHighBidder !== '' && currentHighBidder === discordId.toString(),
      myActiveBid, myActiveBidAlt,
      winnerIsMe: isEnded && settled && myWonThisAuction,
      winningBid: isEnded && settled && currentHighBidder !== '' ? currentHighBid : null,
      requiredRoleNames, hasRolePermission,
      roleRequirementMode, roleRequirementMinCount,
      category,
      altCurrency, altCurrencyDisplay, altCurrencyRate, altCurrencyBalance,
      extendTriggerMin, extendByMin,
      sortOrder,
      winnerCount, raffleSlots,
      raffleDrawn: !!raffleResultRaw, myRafflePrize,
    });
  }

  auctions.sort((a, b) => {
    const oa = a.sortOrder === null ? Infinity : a.sortOrder;
    const ob = b.sortOrder === null ? Infinity : b.sortOrder;
    return oa - ob;
  });

  return { status: 'success', auctions, categoryOrder };
}

