      if (!isFinite(amt) || amt === 0 || Math.abs(amt) > 1000000 || (type === 'item' && amt < 0)) return { error: '「' + name + '」的「' + nm + '」數量不正確(1~1000000;貨幣可填負數=陷阱扣除,道具不行)' };
