  out.prizes = prizes; out.blankName = s(c.blankName, 20) || '銘謝惠顧';
  out.cooldownSec = c.cooldownSec !== undefined ? int(c.cooldownSec, 0, 604800, 0) : int((parseInt(c.cooldownMin, 10) || 0) * 60, 0, 604800, 0); out.maxPerPlayer = int(c.maxPerPlayer, 0, 1000, 0); out.maxPerDay = int(c.maxPerDay, 0, 1000, 0);
