  for (const c of (rs.results || [])) { n++; if (c.taken_by && (c.taken_at || '') >= lastAt) { lastAt = c.taken_at || ''; lastUid = c.taken_by; } if (c.taken_by) { taken[c.idx] = pokeLabel_(board.cfg, c.pi); const pz = c.pi >= 0 && board.cfg.prizes && board.cfg.prizes[c.pi]; if (pz && pz.showWinners) wl.push({ pi: c.pi, uid: c.taken_by, at: c.taken_at || '' }); } else { left++; leftBy[c.pi] = (leftBy[c.pi] || 0) + 1; } if (revealAll) all[c.idx] = pokeLabel_(board.cfg, c.pi); }
