  if (wl.length) { wl.sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0)); const w = {}; for (const x of wl) (w[x.pi] = w[x.pi] || []).push(x.uid); leftBy.w = w; }
  if (left === 0 && n > 0 && lastUid && board.cfg.lastPrize && board.cfg.lastPrize.enabled) leftBy.lw = lastUid; // 全部戳完:最後賞得主
  return { taken, all: revealAll ? all : undefined, left, total: n, leftBy };
