    for (const r of (rs.results || [])) { const bd = await pokeBoard_(env, r.id); const t = await pokeTaken_(env, bd, bd.status === 'closing'); boards.push({ id: bd.id, status: bd.status, cfg: bd.cfg, msg: bd.msg, taken: t.taken, all: t.all, leftBy: t.leftBy }); }
