    const fee = c.cost && c.cost.amount > 0 && c.cost.currency ? c.cost : null, feeTag = id + '-' + pid + '-' + nowMs + '-' + idx;
    const feeGrant = (sign, claim) => ({ claimId: claim, discordId: pid, rewardType: 'currency', currency: fee.currency, amount: sign * fee.amount, reason: ('戳戳樂' + (sign < 0 ? '費用:' : '退費:') + bd.name).slice(0, 40), noNegative: sign < 0, noCombo: sign > 0 });
