    birthdayRoleId: '1531652769948373134', adminRoleIds: ['1363550279173144809', '988808734241333299', '1455903574952382565'],
    webhookAvatar: 'https://i.meee.com.tw/bqI81Ay.webp', webhookName: '幕後煮屎人',
