    let ids;
    if (which === 'all') ids = (((await env.DB.prepare("SELECT id FROM boss_gift WHERE uid=? AND (expire_ts IS NULL OR expire_ts=0 OR expire_ts>" + Date.now() + ") AND (status='pending' OR (status='claiming' AND claimed_ts<?)) ORDER BY id LIMIT 40").bind(uid, lockOld).all()).results) || []).map((x) => x.id);
    else { const n = parseInt(which, 10); ids = isFinite(n) ? [n] : []; }
