  const okId = (x) => /^\d{15,22}$/.test(x);
  if (action === 'botQuestCfg') {
    return { status: 'success', cfg: { enabled: cfg.enabled, currency: cfg.currency, checkNeed: cfg.checkNeed, abandonCost: cfg.abandonCost, adminRoleIds: cfg.adminRoleIds, thread: cfg.thread, threadName: cfg.threadName, panelText: cfg.panelText, panelButton: cfg.panelButton } };
  }
