    { const nowTp = new Date(now + 8 * 3600 * 1000).toISOString().slice(0, 16); // 台灣時間分鐘
      if (cfg.startAt && nowTp < cfg.startAt) return { status: 'success', deny: '互檢任務尚未開始,開始時間:' + cfg.startAt.replace('T', ' ') };
      if (cfg.endAt && nowTp >= cfg.endAt) return { status: 'success', deny: '互檢任務已經結束(' + cfg.endAt.replace('T', ' ') + ')' }; }
    const pool = cfg.tasks.split('\n').filter(Boolean);
