        if (rj) { const bg = questBlindGrants_(rj, 'qdone-' + owner + '-' + seq, owner, '互檢任務完成'); grants.push(...bg.grants); ownerLabel = bg.label; }
        else if (Number(st.reward) > 0) { ownerIdxs.push(grants.length); ownerLabel = Number(st.reward) + '個' + cfg.currency; grants.push({ claimId: 'qdone-' + owner + '-' + seq, discordId: owner, rewardType: 'currency', currency: cfg.currency, amount: Number(st.reward), reason: '互檢任務完成' }); }
        ms = cfg.milestones.find((m) => m.count === newDone) || null;
