    let content = '';
    if (day.mul !== 1) content += (day.big ? '## ' : '### ') + '本日完成幻彩水晶' + day.mul + '倍!\n';
    content += (cfg.pingRoleId ? '<@&' + cfg.pingRoleId + '>\n' : '') + '各位團員!團任時間:D!\n有空的團員歡迎到騎士團農場集合!\n';
    if (day.festival) content += (day.mul === 2 ? '\n## ' : '') + day.festival + '\n';
