    const uid = String(b.userId || '');
    if (!/^\d{15,22}$/.test(uid)) return { status: 'error', message: '缺少玩家ID' };
    const date = today;
    if (!b.test) { // 測試:不佔今日名額
      const r = await env.DB.prepare('INSERT OR IGNORE INTO group_reward_cfg (k,v,updated) VALUES (?,?,?)').bind('chopen:' + date + ':' + uid, '1', nowIso).run();
      if (!(r && r.meta && r.meta.changes)) return { status: 'success', already: true };
    }
    const day = await challengeDay_(env, cfg, date);
    const pick = (a) => (a && a.length ? a[Math.floor(Math.random() * a.length)] : '');
    // 限定日期組有符合今天 → 只用符合的(取代平常的);沒有才用平常的
    const setsToday = (sets) => (sets || []).filter((x) => date >= x.start && date <= x.end);
    const pzSets = setsToday(cfg.puzzleSets);
    const puzzlePool = pzSets.length ? pzSets.flatMap((x) => x.text.split(/\r?\n/).filter(Boolean)) : cfg.puzzles;
    const bdSets = setsToday(cfg.blindSets);
    const blindText = bdSets.length ? bdSets.map((x) => x.text).join('\n') : cfg.blindRewards;
    let puzzle = pick(puzzlePool) || '(後台還沒設定挑戰題目)';
    if (b.birthday) puzzle = '生日快樂! 本日個人挑戰PASS!';
    // 依權重抽一列;x=基本量×當日倍數、+=固定量
    const rows = cfg.rewardRows || [];
