  meta.forEach(([sc, p], i) => { if (lockMsg) return; const lim = +(sc === 'G' ? c.shared : c.personal)[p], u = got[keys[i]] || 0; if (u >= lim) lockMsg = (sc === 'G' ? '全服' : '你的') + CAT_PNAME_[p] + '額度(' + (c.unit || '點數') + ')已用完 ' + u + '/' + lim + ',' + b[p].reset + ' 解鎖'; });
  return { lockMsg, rem };
