    const m = seg.trim().match(/^(.+?)\s*[:：]\s*(\d+(?:\.\d+)?)$/); if (!m) return;
    const name = m[1].trim(), v = parseFloat(m[2]), g = ((cfg && cfg.cats) || {})[name]; if (!g || !catHasLimit_(g) || !(v >= 0)) return;
