      if (r && r.item) { rw.item = true; if (lo < 1 || lo !== Math.floor(lo)) return { error: '「' + nm + '」道具「' + cur + '」數量要是 1 以上的整數' }; }
      if (!isNaN(mx) && mx > lo) { if (rw.item && mx !== Math.floor(mx)) return { error: '「' + nm + '」道具「' + cur + '」隨機上限要是整數' }; if (mx > 1000000) return { error: '「' + nm + '」的「' + cur + '」隨機上限太大(最多 1000000)' }; rw.max = Math.round(mx * 100) / 100; }
